// Hydration is a compatibility bridge for the in-memory domain service. Keep
// it request-safe without reloading every snapshot on every request; all
// server-side persistence helpers invalidate this entry after a successful
// write. Cross-instance updates may be observed within this short TTL.
const workspaceHydrationInFlight = new Map<string, Promise<void>>()
const workspaceHydratedAt = new Map<string, number>()
const workspaceHydrationGeneration = new Map<string, number>()
const WORKSPACE_HYDRATION_TTL_MS = 1_000
function invalidateWorkspaceHydration(workspaceId: string) {
  for (const key of workspaceHydratedAt.keys()) if (key === workspaceId || key.startsWith(`${workspaceId}:`)) workspaceHydratedAt.delete(key)
  workspaceHydrationGeneration.set(workspaceId, (workspaceHydrationGeneration.get(workspaceId) ?? 0) + 1)
}
