type ExecutionModality = 'content' | 'image' | 'image_edit' | 'ocr' | 'video'

/**
 * Keep merchant-facing execution truth at the API boundary. Application
 * services intentionally have deterministic local fallbacks for tests and
 * fixture workflows, so a completed result is not sufficient evidence that a
 * provider was called.
 */
export function executionContract(modality: ExecutionModality, providerExecuted: boolean, providerKind?: string) {
  const labels: Record<ExecutionModality, { provider: string; simulated: string }> = {
    content: { provider: '已由配置的内容模型生成', simulated: '本地演示文案，未调用内容模型' },
    image: { provider: '已由配置的图片模型生成', simulated: '本地演示图片，未调用图片模型' },
    image_edit: { provider: '已由配置的图片编辑模型生成', simulated: '本地演示图片编辑结果，未调用图片编辑模型' },
    ocr: { provider: '已由配置的 OCR 模型解析', simulated: '本地解析器结果，未调用 OCR 模型' },
    video: { provider: '已由配置的视频模型执行', simulated: '视频脚本/分镜演示结果，未调用视频模型' },
  }
  const label = providerExecuted ? labels[modality].provider : labels[modality].simulated
  return {
    mode: providerExecuted ? 'provider' as const : 'simulated' as const,
    simulated: !providerExecuted,
    providerExecuted,
    ...(providerKind ? { providerKind } : {}),
    label,
    message: label,
  }
}

async function contentExecutionEvidence(workspaceId: string, actionId: string) {
  await persistenceReady
  const rows = await (persistence.modelUsage ?? memoryModelUsage).listByAction(workspaceId, actionId)
  const receipt = rows
    .filter(item => item.modality === 'text')
    .slice()
    .sort((left, right) => right.revision - left.revision || Date.parse(right.observedAt) - Date.parse(left.observedAt))[0]
  const usage = receipt && (receipt.inputTokens !== undefined || receipt.outputTokens !== undefined || receipt.totalTokens !== undefined)
    ? {
        ...(receipt.inputTokens !== undefined ? { inputTokens: receipt.inputTokens } : {}),
        ...(receipt.outputTokens !== undefined ? { outputTokens: receipt.outputTokens } : {}),
        ...(receipt.totalTokens !== undefined ? { totalTokens: receipt.totalTokens } : {}),
      }
    : undefined
  const settled = Boolean(
    receipt
    && receipt.settlementStatus === 'settled'
    && receipt.providerRequestId?.trim()
    && usage
    && receipt.costCny !== undefined,
  )
  return {
    ...executionContract('content', settled, receipt?.model),
    ...(receipt?.providerRequestId ? { providerRequestId: receipt.providerRequestId } : {}),
    ...(usage ? { usage } : {}),
    ...(receipt?.costCny !== undefined ? { costCny: receipt.costCny } : {}),
    ...(receipt ? { settlementStatus: receipt.settlementStatus, actionId } : {}),
  }
}

function controlledRelayEnvironment() {
  return ['staging', 'preview', 'production'].includes(process.env.NODE_ENV ?? '')
}

function durableContentGenerationEnvironment() {
  return isProduction() || process.env.LOCAL_COMPOSE === 'true'
}

async function requireSettledContentExecutionEvidence(workspaceId: string, actionId: string) {
  const execution = await contentExecutionEvidence(workspaceId, actionId)
  if (controlledRelayEnvironment() && execution.providerExecuted !== true) {
    throw new DomainError('MODEL_RELAY_EVIDENCE_REQUIRED', '中转模型回执尚未完成，内容暂不能交付', 409, {
      operation_status: 'pending_receipt',
      action_id: actionId,
      missing: ['provider_request_id', 'usage', 'cost_cny', 'settlement'],
    })
  }
  return execution
}

