/** Keep Ops storage status useful without turning reconciliation into an object browser. */
export function redactStorageReconciliation(report?: ReconciliationReport) {
  if (!report) return { status: 'unavailable' as const, message: '尚未收到对象清单对账结果' }
  const findingCounts: Record<string, number> = {}
  for (const finding of report.findings) findingCounts[finding.code.toLowerCase()] = (findingCounts[finding.code.toLowerCase()] ?? 0) + 1
  const parsedRunAt = report.lastRunAt ? Date.parse(report.lastRunAt) : NaN
  const ageMs = Number.isFinite(parsedRunAt) ? Date.now() - parsedRunAt : NaN
  const freshness = !Number.isFinite(ageMs) ? 'unknown' : ageMs > 72 * 60 * 60 * 1000 ? 'expired' : ageMs > 24 * 60 * 60 * 1000 ? 'stale' : 'fresh'
  const failed = report.runStatus === 'failed'
  return { status: failed ? 'failed' as const : report.status, runStatus: report.runStatus ?? 'succeeded' as const, errorMessage: failed ? '对账提供方失败，请检查对象清单、数据库和定时任务后重试。' : undefined, lastRunAt: report.lastRunAt ?? null, freshness, freshnessAfterMinutes: 24 * 60, quota: { ...report.quota }, counts: { ...report.counts }, findingCounts }
}

