let durableKnowledgeRepository: KnowledgeRepository | undefined

/**
 * Load the approved durable product/SKU knowledge immediately before a
 * generation snapshot is frozen.  All generation transports must use this
 * helper: otherwise MCP and REST can silently produce different contexts.
 * The repository enforces workspace, product/store, approval, rights and
 * index-state boundaries; this function only projects the bounded result into
 * the application snapshot and never mutates durable data.
 */
function durableKnowledgeBlocker(documents: readonly KnowledgeDocument[]) {
  const live = documents.filter(document => document.indexState !== 'deleted')
  const review = live.filter(document => document.approvalStatus !== 'approved' || document.rightsStatus !== 'cleared')
  const failed = live.filter(document => document.indexState === 'failed')
  const pending = live.filter(document => document.indexState !== 'ready')
  const blocked = review.length ? review : failed.length ? failed : pending
  if (!blocked.length) return undefined
  return {
    code: review.length ? 'KNOWLEDGE_REVIEW_REQUIRED' : failed.length ? 'KNOWLEDGE_INDEX_FAILED' : 'KNOWLEDGE_INDEX_PENDING',
    message: review.length
      ? '商品知识尚未通过审批或权益确认，请先完成知识资产审核，再生成内容。'
      : failed.length
        ? '商品知识索引失败，请联系平台检查真实索引链路并完成重试；无需重复审批，索引成功前不能生成内容。'
        : '商品知识仍在等待索引，请由平台完成真实索引链路；无需重复审批，索引就绪前不能生成内容。',
  }
}

function sameKnowledgeDocumentVersion(left: KnowledgeDocument, right: KnowledgeDocument) {
  return left.id === right.id
    && left.workspaceId === right.workspaceId
    && left.productId === right.productId
    && left.revision === right.revision
    && left.contentHash === right.contentHash
    && left.indexState === right.indexState
    && left.approvalStatus === right.approvalStatus
    && left.rightsStatus === right.rightsStatus
}

function requireUnchangedKnowledgeContext(input: {
  workspaceId: string
  productId: string
  first: readonly KnowledgeDocument[]
  final: readonly KnowledgeDocument[]
  candidates: readonly KnowledgeDocument[]
}) {
  const scoped = (documents: readonly KnowledgeDocument[]) => documents
    .filter(document => document.workspaceId === input.workspaceId && document.productId === input.productId && document.indexState !== 'deleted')
  const first = scoped(input.first)
  const final = scoped(input.final)
  const blocker = durableKnowledgeBlocker(final)
  if (blocker) throw new DomainError(blocker.code, blocker.message, 409, { ...blocker, product_id: input.productId })
  const finalById = new Map(final.map(document => [document.id, document]))
  const firstById = new Map(first.map(document => [document.id, document]))
  const unchanged = firstById.size === first.length
    && finalById.size === final.length
    && firstById.size === finalById.size
    && first.every(document => {
      const current = finalById.get(document.id)
      return current !== undefined && sameKnowledgeDocumentVersion(document, current)
    })
    && new Set(input.candidates.map(document => document.id)).size === input.candidates.length
    && input.candidates.every(document => {
      const current = finalById.get(document.id)
      return current !== undefined
        && document.workspaceId === input.workspaceId
        && document.productId === input.productId
        && current.indexState === 'ready'
        && current.approvalStatus === 'approved'
        && current.rightsStatus === 'cleared'
        && sameKnowledgeDocumentVersion(document, current)
    })
  if (!unchanged) throw new DomainError('KNOWLEDGE_CONTEXT_CHANGED', '商品知识在生成前发生变化，请重新查询知识状态后重试', 409, { product_id: input.productId, next_action: 'catalog.search' })
}

async function hydrateDurableKnowledgeForGeneration(task: { id: string; workspaceId: string; productId: string; candidateOnly?: boolean }, commit = true): Promise<ReadonlyArray<{ id: string; title: string; content: string; revision: number }> | undefined> {
  const repository = persistence.knowledge ?? durableKnowledgeRepository
  if (task.candidateOnly && !repository) throw new DomainError('KNOWLEDGE_REPOSITORY_UNAVAILABLE', '候选任务需要可验证的商品知识仓储；当前未配置，已停止生成', 503, { product_id: task.productId })
  const product = service.products.get(task.productId)
  if (!repository || !product || product.workspaceId !== task.workspaceId) return
  const documents = (await repository.listDocuments(task.workspaceId, { productId: product.id }))
    .filter(document => document.workspaceId === task.workspaceId && document.productId === product.id)
  if (task.candidateOnly && !documents.some(document => document.indexState !== 'deleted')) throw new DomainError('KNOWLEDGE_CONTEXT_NOT_READY', '候选商品没有可用的已审核知识资料，索引就绪前不能生成内容', 409, { product_id: product.id, next_action: 'knowledge.asset.list' })
  const blocker = durableKnowledgeBlocker(documents)
  if (blocker) throw new DomainError(blocker.code, blocker.message, 409, { ...blocker, product_id: product.id })
  const results = await repository.search({
    workspaceId: task.workspaceId,
    platform: product.platform,
    ...(product.accountId ? { accountId: product.accountId } : {}),
    ...(product.storeName ? { storeName: product.storeName } : {}),
    productId: product.id,
    limit: 8,
  })
  const finalDocuments = await repository.listDocuments(task.workspaceId, { productId: product.id })
  requireUnchangedKnowledgeContext({ workspaceId: task.workspaceId, productId: product.id, first: documents, final: finalDocuments, candidates: results.map(result => result.document) })
  if (results.length === 0) {
    if (documents.some(document => document.indexState === 'ready' && document.approvalStatus === 'approved' && document.rightsStatus === 'cleared')) {
      throw new DomainError('KNOWLEDGE_CONTEXT_UNAVAILABLE', '商品知识已就绪，但检索未返回可用知识；请检查知识与商品、店铺及账号的绑定和索引状态，修复后重试', 409, { product_id: product.id, next_action: 'catalog.search' })
    }
  }
  const selectedDocuments = results.map(({ document, chunks }) => {
    const content = chunks.length ? chunks.map(chunk => chunk.content).join('\n') : document.extractedText
    if (content.length > 8_000) {
      throw new DomainError('KNOWLEDGE_CONTEXT_TOO_LARGE', '商品知识内容超过单份生成上下文上限（8000 字符）；请缩短或拆分知识来源并完成重新审核、索引后重试', 413, { product_id: product.id, document_id: document.id, content_length: content.length, limit: 8_000, next_action: null })
    }
    return { id: document.id, title: document.title, content, revision: document.revision }
  })
  if (commit) service.setDurableKnowledgeDocuments(task.id, selectedDocuments)
  return selectedDocuments
}

async function recheckWorkerGenerationKnowledge(event: {
  id: string
  workspaceId: string
  aggregateId: string
  payload: Record<string, unknown>
}, attempt: { number: number; key: string; bodyHash: string; nonce: string }) {
  const rawInput = event.payload.input
  const input = rawInput && typeof rawInput === 'object' && !Array.isArray(rawInput) ? rawInput as Record<string, unknown> : undefined
  const rawProduct = input?.product
  const productInput = rawProduct && typeof rawProduct === 'object' && !Array.isArray(rawProduct) ? rawProduct as Record<string, unknown> : undefined
  const productId = typeof productInput?.id === 'string' ? productInput.id.trim() : ''
  const platform = typeof input?.platform === 'string' ? input.platform.trim() : ''
  const taskId = typeof event.payload.task_id === 'string' ? event.payload.task_id.trim() : ''
  const contextHash = typeof event.payload.context_hash === 'string' ? event.payload.context_hash : ''
  const rawKnowledge = input?.knowledgeContext
  const knowledge = rawKnowledge && typeof rawKnowledge === 'object' && !Array.isArray(rawKnowledge) ? rawKnowledge as Record<string, unknown> : undefined
  const frozen = knowledge?.documents === undefined ? [] : knowledge.documents
  const attemptBound = Number.isSafeInteger(attempt.number) && attempt.number >= 0
    && /^mm-[a-f0-9]{64}$/u.test(attempt.key)
    && /^[a-f0-9]{64}$/u.test(attempt.bodyHash)
    && /^[A-Za-z0-9_-]{22,128}$/u.test(attempt.nonce)
  if (!input || !productId || !platform || !taskId || !/^[a-f0-9]{64}$/u.test(contextHash)
    || contextEnvelopeHash(input) !== contextHash || !Array.isArray(frozen)
    || frozen.length > MAX_FROZEN_GENERATION_KNOWLEDGE_DOCUMENTS || !attemptBound) {
    throw new DomainError('KNOWLEDGE_EXECUTION_SNAPSHOT_INVALID', '生成事件缺少有效的冻结知识或 provider attempt 身份，已阻止模型调用', 409)
  }
  if (frozen.some(document => !document || typeof document !== 'object' || Array.isArray(document)
    || typeof (document as Record<string, unknown>).id !== 'string'
    || typeof (document as Record<string, unknown>).title !== 'string'
    || typeof (document as Record<string, unknown>).content !== 'string'
    || !Number.isSafeInteger((document as Record<string, unknown>).revision))) {
    throw new DomainError('KNOWLEDGE_EXECUTION_SNAPSHOT_INVALID', '生成事件中的冻结知识文档无效，已阻止模型调用', 409)
  }

  try { await hydrateWorkspace(event.workspaceId, { readOnly: true }) }
  catch { throw new DomainError('KNOWLEDGE_EXECUTION_RECHECK_UNAVAILABLE', '商品知识执行复核无法加载工作区状态，已阻止模型调用', 503) }
  let task: Task
  try {
    const job = service.getGenerationJob(event.workspaceId, event.aggregateId)
    task = service.getTask(job.taskId)
    const product = service.products.get(productId)
    if (!product || job.taskId !== taskId || task.id !== taskId || task.workspaceId !== event.workspaceId
      || task.productId !== productId || task.platform !== platform || product.workspaceId !== event.workspaceId
      || product.platform !== platform) {
      throw new DomainError('KNOWLEDGE_EXECUTION_CHANGED', '生成事件与当前任务、商品或工作区的绑定不一致，已阻止模型调用', 409)
    }
  } catch (error) {
    if (error instanceof DomainError && error.code === 'KNOWLEDGE_EXECUTION_CHANGED') throw error
    throw new DomainError('KNOWLEDGE_EXECUTION_CHANGED', '生成事件与当前任务、商品或工作区的绑定不一致，已阻止模型调用', 409)
  }
  let selected: Awaited<ReturnType<typeof hydrateDurableKnowledgeForGeneration>>
  try { selected = await hydrateDurableKnowledgeForGeneration(task, false) }
  catch (error) {
    if (error instanceof DomainError && /^KNOWLEDGE_(?:REVIEW|INDEX|CONTEXT)/u.test(error.code)) throw error
    throw new DomainError('KNOWLEDGE_EXECUTION_RECHECK_UNAVAILABLE', '商品知识执行复核失败，已阻止模型调用', 503)
  }
  if (!selected) throw new DomainError('KNOWLEDGE_EXECUTION_RECHECK_UNAVAILABLE', '商品知识持久仓储不可用，已阻止模型调用', 503)
  if (selected.length !== frozen.length || frozen.some((old, index) => {
    const current = selected![index]
    const previous = old as Record<string, unknown>
    return !current || current.id !== previous.id || current.revision !== previous.revision
      || current.title !== previous.title || current.content !== previous.content
  })) {
    throw new DomainError('KNOWLEDGE_EXECUTION_CHANGED', '商品知识在任务入队后发生变化，已阻止模型调用', 409)
  }
  return {
    ready: true,
    event_id: event.id,
    aggregate_id: event.aggregateId,
    workspace_id: event.workspaceId,
    task_id: taskId,
    product_id: productId,
    context_hash: contextHash,
    document_count: frozen.length,
    content_hash: generationKnowledgeReceiptHash(frozen as Array<{ id: string; title: string; content: string; revision: number }>),
    attempt: attempt.number,
    provider_attempt_key: attempt.key,
    request_body_sha256: attempt.bodyHash,
    request_nonce: attempt.nonce,
    checked_at: new Date().toISOString(),
  }
}
const memoryStorageQuota = new MemoryStorageQuotaRepository()
const memoryStorageReconciliation = new MemoryReconciliationStatusStore()
const memoryReconciliationStatuses = new MemoryReconciliationStatusRepository()

/** Durable projection adapter: Ops may read status, never object keys or payloads. */
class DurableReconciliationStatusStore implements ReconciliationStatusStore {
  constructor(private readonly repository: ReconciliationStatusRepository) {}
  async put(report: ReconciliationReport) {
    await this.repository.upsert({
      workspaceId: report.workspaceId,
      resourceType: 'storage_inventory',
      resourceId: 'workspace',
      status: report.runStatus === 'failed' ? 'failed' : report.status === 'clean' ? 'succeeded' : 'manual_attention',
      idempotencyKey: `storage-reconciliation:${report.lastRunAt ?? 'unknown'}`,
      details: report as unknown as Record<string, unknown>,
      observedAt: report.lastRunAt,
    })
  }
  async get(workspaceId: string) {
    const record = await this.repository.getLatest({ workspaceId, resourceType: 'storage_inventory', resourceId: 'workspace' })
    return record?.details as unknown as ReconciliationReport | undefined
  }
  async list(workspaceId: string) {
    const records = await this.repository.list({ workspaceId, resourceType: 'storage_inventory' })
    return records.map(record => record.details as unknown as ReconciliationReport)
  }
}

/** The worker has no database or object-store credentials. It requests one
 * workspace-scoped run and the API assembles both sides inside its trust
 * boundary. */
async function runWorkspaceStorageReconciliation(workspaceId: string) {
  const inventory = async (): Promise<readonly ObjectInventoryEntry[]> => (await getAssetStorage().list(workspaceId)).map(item => ({ workspaceId: item.workspaceId, storageKey: item.key, sha256: item.sha256, sizeBytes: item.sizeBytes }))
  const references = async (): Promise<readonly DurableObjectReference[]> => {
    const snapshots = persistence.business
      ? await persistence.business.loadWorkspace(workspaceId, { excludeEntityTypes: ['product', 'task', 'content_version', 'publish_job', 'publish_batch', 'platform_account', 'generation_job', 'image_generation_job', 'brand_profile', 'feedback', 'sync_job', 'automation_policy'] })
      : []
    // In Postgres, an empty asset result is authoritative. Falling back to the
    // in-memory service here could silently hide durable deletions or report a
    // stale subset when hydration was intentionally bounded.
    const assets = persistence.business ? snapshots.filter(snapshot => snapshot.entityType === 'asset') : service.listAssets(workspaceId)
    return assets.flatMap(asset => {
      const payload = 'payload' in asset ? asset.payload : asset
      const storageKey = typeof payload.storageKey === 'string' ? payload.storageKey.trim() : ''
      const sha256 = typeof payload.sha256 === 'string' ? payload.sha256.trim() : ''
      const sizeBytes = payload.sizeBytes
      if (!storageKey) return []
      if (!/^[a-f0-9]{64}$/iu.test(sha256) || !Number.isSafeInteger(sizeBytes) || Number(sizeBytes) < 0) throw new DomainError('STORAGE_REFERENCE_INVALID', '素材持久化引用缺少合法 sha256 或 sizeBytes，已阻止对账写入', 503)
      const assetId = 'entityId' in asset ? asset.entityId : typeof payload.id === 'string' ? payload.id : ''
      if (!assetId) throw new DomainError('STORAGE_REFERENCE_INVALID', '素材持久化引用缺少 asset_id，已阻止对账写入', 503)
      return [{ workspaceId, assetId, storageKey, sha256, sizeBytes: Number(sizeBytes) }]
    })
  }
  const quota = persistence.storageQuota ? await persistence.storageQuota.getSnapshot(workspaceId) : undefined
  const status = persistence.storageReconciliation ?? memoryStorageReconciliation
  const result = await runReconciliationCycle({
    workspaces: [workspaceId],
    inventory: { list: inventory },
    references: { list: references },
    ...(quota ? { quota: { get: async () => ({ limitBytes: quota.limitBytes, reservedBytes: quota.reservedBytes }) } } : {}),
    status,
  })
  return result.reports[0] ?? { workspaceId, status: 'attention_required' as const, runStatus: 'failed' as const, error: { code: 'STORAGE_RECONCILIATION_EMPTY', message: '对象对账未生成报告' }, quota: { reservedBytes: 0, usedBytes: 0, projectedBytes: 0 }, counts: { references: 0, inventoryObjects: 0, matched: 0, missing: 0, metadataMismatches: 0, orphans: 0, crossWorkspace: 0, duplicates: 0 }, findings: [] }
}

