const memoryAuditCenter: AuditCenterRepository = {
  async list(query) {
    const operations = await memoryOperations.list(query.workspaceId, 5_000)
    return new MemoryAuditCenterRepository(operations.map(item => ({ id: item.id, source: 'operation' as const, workspace_id: item.workspaceId, actor_id: item.actorId, action: item.action, resource_type: item.resourceType, resource_id: item.resourceId, reason: item.reason, occurred_at: item.createdAt, evidence: { before: item.before, after: item.after } }))).list(query)
  },
  async detail(workspaceId, source, id) {
    if (source !== 'operation') return undefined
    const operations = await memoryOperations.list(workspaceId, 5_000)
    return new MemoryAuditCenterRepository(operations.map(item => ({ id: item.id, source: 'operation' as const, workspace_id: item.workspaceId, actor_id: item.actorId, action: item.action, resource_type: item.resourceType, resource_id: item.resourceId, reason: item.reason, occurred_at: item.createdAt, evidence: { before: item.before, after: item.after } }))).detail(workspaceId, source, id)
  },
  async exportRows(query, limit) {
    const operations = await memoryOperations.list(query.workspaceId, Math.min(5_001, limit + 1))
    return new MemoryAuditCenterRepository(operations.map(item => ({ id: item.id, source: 'operation' as const, workspace_id: item.workspaceId, actor_id: item.actorId, action: item.action, resource_type: item.resourceType, resource_id: item.resourceId, reason: item.reason, occurred_at: item.createdAt, evidence: { before: item.before, after: item.after } }))).exportRows(query, limit)
  },
}
