async function requestCatalogSync(workspaceId: string, req: IncomingMessage, params: JsonObject) {
  const platform = required(params, 'platform') as Platform
  if (!platformConnectorConfigured(platform)) throw new DomainError('NOT_CONFIGURED', `${platform} 官方 API 尚未配置，无法同步商品`, 503)
  const accountId = (typeof params.account_id === 'string' && params.account_id.trim()) || header(req, 'x-account-id')?.trim() || (isProduction() ? '' : defaultFixtureAccountId(workspaceId, platform))
  if (!accountId) throw new DomainError('PLATFORM_ACCOUNT_REQUIRED', '生产同步必须指定已授权平台账号', 400)
  const platformAccount = isProduction() || fixtureMode ? requireActivePlatformAccount(workspaceId, accountId, platform) : undefined
  await ensureFixtureAccount(workspaceId, platform, accountId)
  const job = service.createSyncJob({ workspaceId, platform, accountId, mode: params.mode === 'full' ? 'full' : 'incremental', ...(typeof params.cursor === 'string' && params.cursor.trim() ? { cursor: params.cursor } : {}) })
  const authorizationSnapshot = workerAuthorizationSnapshot(req, workspaceId, job.id, 'catalog.sync.execute', { method: 'catalog.sync.start', platform, account_id: accountId, mode: job.mode, resource_revision: job.revision, ...(job.resumeCursor ? { cursor: job.resumeCursor } : {}) })
  if (requiresStrictAuth() && !authorizationSnapshot) {
    service.removeSyncJob(workspaceId, job.id)
    throw new DomainError('AUTHZ_EXECUTION_SNAPSHOT_REQUIRED', '商品同步缺少持久身份授权快照，已拒绝入队', 503)
  }
  try {
    await persistSnapshot(workspaceId, 'sync_job', job, job as unknown as Record<string, unknown>)
    await persistEvent(workspaceId, job.id, 'sync.requested', job.revision, { job_id: job.id, platform, account_id: accountId, mode: job.mode, ...(job.resumeCursor ? { cursor: job.resumeCursor } : {}), ...(authorizationSnapshot ? { authorization_snapshot: serializedWorkerAuthorizationSnapshot(authorizationSnapshot) } : {}) })
  } catch (error) {
    const failed = service.updateSyncJob(workspaceId, job.id, { state: 'failed', errorMessage: error instanceof Error ? error.message : '同步任务持久化失败' })
    let failureProjected = false
    try {
      await persistSnapshot(workspaceId, 'sync_job', failed, failed as unknown as Record<string, unknown>)
      await persistEvent(workspaceId, job.id, 'sync.failed', failed.revision, { job_id: job.id, platform, account_id: accountId, error_message: failed.errorMessage ?? '同步任务持久化失败' })
      failureProjected = true
    } catch { /* preserve the original failure; remove the in-memory ghost below */ }
    if (!failureProjected) service.removeSyncJob(workspaceId, job.id)
    throw error
  }
  if (fixtureMode) {
    try {
      const synced = await connectorRuntime.sync(platform, { workspaceId, accountId, ...(platformAccount ? { credentialRef: platformAccount.credentialRef } : {}), traceId: requestId(req) }, job.resumeCursor)
      const products = service.upsertSyncedProducts({ workspaceId, platform, accountId, items: synced.items })
      await invalidateCanonicalFactsAfterSync(workspaceId, products)
      const completed = service.updateSyncJob(workspaceId, job.id, { state: 'succeeded', pages: synced.pages, itemsUpserted: products.length, itemsFailed: 0, failedItems: [], nextCursor: undefined, resumeCursor: undefined })
      for (const product of products) await persistSnapshot(workspaceId, 'product', product, product as unknown as Record<string, unknown>)
      await persistSnapshot(workspaceId, 'sync_job', completed, completed as unknown as Record<string, unknown>)
      await persistEvent(workspaceId, job.id, 'sync.completed', completed.revision, { job_id: job.id, platform, account_id: accountId, pages: synced.pages, items_upserted: products.length, simulated: true })
      const automation = await scanAutomationAfterOperationalCompletion(workspaceId, platform, accountId, 'catalog.sync.start.completed')
      return { ...completed, products, simulated: true, automation }
    } catch (error) {
      const failed = service.updateSyncJob(workspaceId, job.id, { state: 'failed', errorMessage: error instanceof Error ? error.message : '同步 provider 调用失败' })
      await persistSnapshot(workspaceId, 'sync_job', failed, failed as unknown as Record<string, unknown>)
      await persistEvent(workspaceId, job.id, 'sync.failed', failed.revision, { job_id: job.id, platform, account_id: accountId, error_message: failed.errorMessage ?? '同步 provider 调用失败', simulated: true })
      throw error
    }
  }
  return job
}

/** Recover a scheduler claim that was persisted immediately before a process
 * crash. A durable sync job proves the claim completed; otherwise requeue the
 * policy immediately instead of waiting for the old future nextRunAt. */
type DurableStateSnapshot = { aggregateId: string; sequence: number; payload: Record<string, unknown> }

function recordInvalidDurableSnapshot(workspaceId: string, entityType: string, entityId: string, error: unknown) {
  const candidate = error as { code?: string; details?: { missing?: unknown } }
  const missing = Array.isArray(candidate.details?.missing) ? candidate.details.missing.filter((item): item is string => typeof item === 'string') : [candidate.code ?? 'unknown']
  const warnings = invalidDurableSnapshots.get(workspaceId) ?? []
  if (!warnings.some(item => item.entityType === entityType && item.entityId === entityId)) warnings.push({ entityType, entityId, missing })
  invalidDurableSnapshots.set(workspaceId, warnings)
}

export function hydrateOutboxSnapshot(workspaceId: string, snapshot: DurableStateSnapshot) {
  const payload = snapshot.payload
  try {
    if (payload.entityType === 'publish_batch') {
      const entity = payload.entity as (PublishBatch & { id?: string }) | undefined
      if (!entity) return
      const batchId = String(entity.id ?? snapshot.aggregateId)
      publishBatches.set(batchId, entity)
      persistedPublishBatches.set(batchId, structuredClone(entity))
    }
    else if (payload.entityType === 'automation_policy') {
      const policy = payload.entity as AutomationPolicy | undefined
      if (policy) automationPolicies.set(automationPolicyKey(workspaceId, policy.platform, policy.accountId), policy)
    }
    else if (payload.entityType === 'merchant_intent' && payload.entity && typeof payload.entity === 'object') {
      merchantIntents.set(`${workspaceId}:${snapshot.aggregateId}`, payload.entity as Record<string, unknown>)
    }
    else if (payload.entityType === 'product' || payload.entityType === 'task' || payload.entityType === 'content_version' || payload.entityType === 'publish_job' || payload.entityType === 'manual_publish_record' || payload.entityType === 'platform_account' || payload.entityType === 'generation_job' || payload.entityType === 'image_generation_job' || payload.entityType === 'brand_profile' || payload.entityType === 'asset' || payload.entityType === 'feedback' || payload.entityType === 'sync_job') {
      service.hydrateSnapshot({ entityType: payload.entityType, entity: payload.entity })
    }
  } catch (error) {
    const entity = payload.entity as { id?: unknown } | undefined
    const entityId = typeof entity?.id === 'string' ? entity.id : snapshot.aggregateId
    recordInvalidDurableSnapshot(workspaceId, typeof payload.entityType === 'string' ? payload.entityType : 'unknown', entityId, error)
  }
}

async function hydrateWorkspaceFromPersistence(workspaceId: string, options: { excludeEntityTypes?: readonly BusinessEntityType[]; readOnly?: boolean } = {}) {
  await persistenceReady
  if (!persistence.business) return
  const durable = await persistence.business.loadWorkspace(workspaceId, options)
  const durableKeys = new Set(durable.map(snapshot => `${snapshot.entityType}:${snapshot.entityId}`))
  for (const snapshot of durable) {
    if (snapshot.entityType === 'publish_batch') {
      const batch = snapshot.payload as unknown as PublishBatch
      publishBatches.set(snapshot.entityId, batch)
      persistedPublishBatches.set(snapshot.entityId, structuredClone(batch))
    }
    else if (snapshot.entityType === 'automation_policy') {
      const policy = snapshot.payload as unknown as AutomationPolicy
      automationPolicies.set(automationPolicyKey(workspaceId, policy.platform, policy.accountId), policy)
    }
    else if (snapshot.entityType === 'merchant_intent') {
      merchantIntents.set(`${workspaceId}:${snapshot.entityId}`, snapshot.payload)
    }
    else {
      try { service.hydrateSnapshot({ entityType: snapshot.entityType, entity: snapshot.payload }) }
      catch (error) {
        // A malformed durable entity must remain unavailable, but it must not
        // prevent unrelated entities in the same workspace from hydrating.
        // Keep the invalid-snapshot evidence for Ops/metrics and continue.
        recordInvalidDurableSnapshot(workspaceId, snapshot.entityType, snapshot.entityId, error)
      }
    }
  }
  const durableOutbox = persistence.outbox as (OutboxRepository & { loadStateSnapshots?: (workspaceId: string, options?: { excludeEntityTypes?: readonly string[] }) => Promise<DurableStateSnapshot[]> }) | undefined
  if (durableOutbox?.loadStateSnapshots) {
    for (const snapshot of await durableOutbox.loadStateSnapshots(workspaceId, options)) {
      const entity = snapshot.payload.entity as { id?: unknown } | undefined
      const entityId = typeof entity?.id === 'string' ? entity.id : snapshot.aggregateId
      if (durable.length && typeof snapshot.payload.entityType === 'string' && durableKeys.has(`${snapshot.payload.entityType}:${entityId}`)) continue
      hydrateOutboxSnapshot(workspaceId, snapshot)
    }
  }
  if (!options.readOnly) await reconcileAutomationClaims(workspaceId)
}

async function hydrateWorkspace(workspaceId: string, options: { excludeEntityTypes?: readonly BusinessEntityType[]; readOnly?: boolean } = {}) {
  const cacheKey = `${workspaceId}:${[...(options.excludeEntityTypes ?? [])].sort().join(',')}:${options.readOnly ? 'read-only' : 'reconcile'}`
  const active = workspaceHydrationInFlight.get(cacheKey)
  if (active) return active
  const hydratedAt = workspaceHydratedAt.get(cacheKey)
  if (hydratedAt !== undefined && Date.now() - hydratedAt < WORKSPACE_HYDRATION_TTL_MS) return
  const generation = workspaceHydrationGeneration.get(workspaceId) ?? 0
  const load = hydrateWorkspaceFromPersistence(workspaceId, options)
    .then(() => { if ((workspaceHydrationGeneration.get(workspaceId) ?? 0) === generation) workspaceHydratedAt.set(cacheKey, Date.now()) })
    .finally(() => { workspaceHydrationInFlight.delete(cacheKey) })
  workspaceHydrationInFlight.set(cacheKey, load)
  return load
}

type WorkspaceMetricsDataReadiness = {
  source: 'durable_repository' | 'memory_service'
  dataCompleteness: 'complete' | 'process_local' | 'partial'
  hydration: {
    status: 'hydrated' | 'not_available'
    attempted: boolean
    invalidSnapshotCount: number
  }
}

/**
 * Metrics must not silently aggregate an empty process-local service after an
 * API restart. The service remains the compatibility read model, but in
 * durable mode it is populated from the workspace-scoped repository before
 * any metric is calculated. A failed durable read is intentionally propagated
 * so callers never receive a plausible-looking partial report.
 */
async function prepareWorkspaceMetricsData(workspaceId: string): Promise<WorkspaceMetricsDataReadiness> {
  await persistenceReady
  if (!persistence.business) {
    return {
      source: 'memory_service',
      dataCompleteness: 'process_local',
      hydration: { status: 'not_available', attempted: false, invalidSnapshotCount: 0 },
    }
  }
  await hydrateWorkspace(workspaceId)
  const invalidSnapshotCount = invalidDurableSnapshots.get(workspaceId)?.length ?? 0
  return {
    source: 'durable_repository',
    dataCompleteness: invalidSnapshotCount ? 'partial' : 'complete',
    hydration: { status: 'hydrated', attempted: true, invalidSnapshotCount },
  }
}

/**
 * Metrics must use the same normalized task projection as the paged task
 * collection. The in-memory service also replays outbox state snapshots for
 * recovery, which is useful for execution but can include orphan snapshots
 * that are not part of the durable task read model.
 */
async function listNormalizedTasksForMetrics(workspaceId: string): Promise<Task[]> {
  if (!persistence.business) return service.listTasks(workspaceId)
  const tasks: Task[] = []
  const limit = 100
  let offset = 0
  while (true) {
    const page = await persistence.business.listTasksPage(workspaceId, { limit, offset })
    tasks.push(...page.items as unknown as Task[])
    if (tasks.length >= page.total || page.items.length === 0) break
    offset += page.items.length
  }
  return tasks
}

function publishEventPayload(job: import('../../../packages/application/src/service.js').PublishJob) {
  const payloadSnapshot = job.payloadSnapshot ?? {}
  const fields = structuredClone(payloadSnapshot.fields ?? {})
  return {
    taskId: job.taskId,
    contentVersionId: job.contentVersionId,
    platform: job.platform,
    workspaceId: job.workspaceId,
    idempotencyKey: job.idempotencyKey,
    ...(job.accountId ? { account_id: job.accountId } : {}),
    // Frozen at prepare time, never `job.remoteId`: the publish payload is built
    // before the write, so a create carries no remote id, while the later
    // reconcile payload would carry the one the platform just returned. The
    // worker derives its per-publish Redis lock key from this value, so the two
    // handlers must read the same field or a create→reconcile pair takes two
    // different keys and the mutual exclusion silently does nothing.
    ...(job.payloadSnapshot?.remoteId ? { remote_id: job.payloadSnapshot.remoteId } : {}),
    fields,
    payload_hash: job.payloadHash,
    media_required: job.selectedVisuals.length > 0,
    ...(job.selectionHash ? { selection_hash: job.selectionHash } : {}),
    ...(job.canonicalBinding ? { canonical_binding: structuredClone(job.canonicalBinding), canonical_binding_hash: job.canonicalBinding.snapshotHash } : {}),
    ...(job.authorizationSnapshot ? { authorization_snapshot: { ...serializedWorkerAuthorizationSnapshot(job.authorizationSnapshot), resource_id: job.id } } : {}),
    image_mode: job.payloadSnapshot?.imageMode ?? 'unchanged',
  }
}

