function fail(res: ServerResponse, status: number, workspaceId: string, code: string, message: string, req?: IncomingMessage, details?: Readonly<Record<string, unknown>>) {
  return send(res, status, workspaceId, null, { code, message, ...(details ? { details } : {}) }, req)
}

const requestBodyCache = new WeakMap<IncomingMessage, Buffer>()

async function requestBodyBytes(req: IncomingMessage, limit: number): Promise<Buffer> {
  const cached = requestBodyCache.get(req)
  if (cached) {
    if (cached.byteLength > limit) throw new DomainError(ERROR_CODES.REQUEST_BODY_TOO_LARGE, '请求体超过允许大小', 413)
    return cached
  }
  const declaredLength = Number(req.headers['content-length'] ?? 0)
  if (Number.isFinite(declaredLength) && declaredLength > limit) throw new DomainError(ERROR_CODES.REQUEST_BODY_TOO_LARGE, '请求体超过允许大小', 413)
  const chunks: Buffer[] = []
  let received = 0
  for await (const chunk of req) {
    const buffer = Buffer.from(chunk)
    received += buffer.byteLength
    if (received > limit) throw new DomainError(ERROR_CODES.REQUEST_BODY_TOO_LARGE, '请求体超过允许大小', 413)
    chunks.push(buffer)
  }
  const bytes = Buffer.concat(chunks)
  requestBodyCache.set(req, bytes)
  return bytes
}

async function body(req: IncomingMessage, requestedLimit = DEFAULT_BODY_LIMIT): Promise<JsonObject> {
  const configuredLimit = Number(process.env.REQUEST_BODY_LIMIT_BYTES ?? requestedLimit)
  const limit = Number.isFinite(configuredLimit) && configuredLimit > 0 ? configuredLimit : DEFAULT_BODY_LIMIT
  const bytes = await requestBodyBytes(req, limit)
  if (!bytes.length) return {}
  try {
    const value: unknown = JSON.parse(bytes.toString('utf8'))
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('not an object')
    return value as JsonObject
  } catch {
    throw new DomainError(ERROR_CODES.INVALID_JSON_BODY, '请求体必须是合法 JSON 对象', 400)
  }
}

async function binaryBody(req: IncomingMessage, limit: number): Promise<Uint8Array> {
  const bytes = await requestBodyBytes(req, limit)
  if (!bytes.length) throw new DomainError('ASSET_BODY_REQUIRED', '素材请求体不能为空', 400)
  return new Uint8Array(bytes)
}

function isProduction() { return process.env.NODE_ENV === 'production' }

export function signedAssetScanCallbackRequired(source: NodeJS.ProcessEnv = process.env) {
  return ['staging', 'preview', 'production'].includes(source.NODE_ENV ?? '')
}

function imageTrace(event: string, fields: Record<string, unknown> = {}) {
  if (isProduction() && process.env.MERCHANT_IMAGE_TRACE_LOGS !== 'true') return
  try { console.info(JSON.stringify({ event: `merchant.image.${event}`, ts: new Date().toISOString(), ...fields })) } catch { /* diagnostics must not affect delivery */ }
}

/**
 * Close the point reservation attached to a durable image request when an
 * execution is authoritatively reconciled as failed.  The reservation id is
 * read from the immutable request outbox event rather than inferred from the
 * UI action key, so gifted/charged requests follow the same accounting path.
 */
async function releaseImageReservationOnFailedReconcile(workspaceId: string, jobId: string, idempotencyKey: string) {
  const repository = persistence.creativePoints
  const outbox = persistence.outbox
  if (!repository || !outbox) return { status: 'not_configured' as const, reservationId: null, points: null }
  const requested = (await outbox.listAggregateEvents(workspaceId, jobId, 100)).find(event => event.eventType === 'image.generation.requested')
  const snapshot = requested?.payload.commercial_access_snapshot
  const reservationId = snapshot && typeof snapshot === 'object' && typeof (snapshot as Record<string, unknown>).reservation_id === 'string'
    ? String((snapshot as Record<string, unknown>).reservation_id).trim()
    : ''
  if (!reservationId) return { status: 'not_found' as const, reservationId: null, points: null }
  const reservation = await repository.getReservation(workspaceId, reservationId)
  if (!reservation) return { status: 'not_found' as const, reservationId, points: null }
  if (reservation.status !== 'active') return { status: reservation.status as 'released' | 'settled', reservationId, points: reservation.points }
  const released = await repository.release({
    workspaceId,
    reservationId,
    idempotencyKey: `image-reconcile-release:${jobId}:${idempotencyKey}`,
    at: new Date().toISOString(),
  })
  imageTrace('reconcile.points_released', { workspace_id: workspaceId, job_id: jobId, reservation_id: reservationId, points: released.value.points })
  return { status: 'released' as const, reservationId, points: released.value.points }
}

/** A Provider result is deliverable only after its original point charge,
 * relay usage receipt, and worker settlement receipt all agree. */
async function requireChargedImageDeliveryEvidence(workspaceId: string, jobId: string, requested: OutboxEvent, providerRequestId: string) {
  const payload = requested.payload
  const actionId = typeof payload.action_id === 'string' ? payload.action_id.trim() : ''
  const reservation = actionId ? await persistence.creativePoints?.getReservationByActionKey?.(workspaceId, actionId) : undefined
  const rawSnapshot = payload.commercial_access_snapshot
  const snapshot = rawSnapshot && typeof rawSnapshot === 'object' && !Array.isArray(rawSnapshot) ? rawSnapshot as Record<string, unknown> : undefined
  const charged = Boolean(reservation) || snapshot?.access_mode === 'POINT_CHARGED' || snapshot?.classification === 'POINT_CHARGED'
  if (!charged) {
    if (isProduction() && snapshot?.access_mode !== 'POINT_REQUIRED_NO_CHARGE') throw new DomainError('IMAGE_GENERATION_COMMERCIAL_SNAPSHOT_INVALID', '图片请求缺少可验证的原始商业执行快照，Provider 结果保持待对账', 409, { reconciliation_required: true, provider_succeeded: true })
    return
  }

  const runKey = typeof payload.run_key === 'string' ? payload.run_key.trim() : ''
  const reservationId = typeof snapshot?.reservation_id === 'string' ? snapshot.reservation_id.trim() : ''
  const job = service.getImageGenerationJob(workspaceId, jobId)
  if (!actionId || runKey !== actionId || !reservationId || payload.job_id !== jobId || payload.workspace_id !== workspaceId || payload.product_id !== job.productId || payload.intent_hash !== job.intentHash
    || (snapshot?.workspace_id !== undefined && snapshot.workspace_id !== workspaceId)
    || (snapshot?.operation !== undefined && snapshot.operation !== 'image_generation.execute')) {
    throw new DomainError('IMAGE_GENERATION_COMMERCIAL_BINDING_INVALID', '图片回执未绑定原始工作区、任务、扣费动作和创意点预留', 409, { reconciliation_required: true, provider_succeeded: true })
  }
  if (!persistence.creativePoints?.getReservationByActionKey || !persistence.creativePointLifecycle || !persistence.modelUsage) {
    throw new DomainError('IMAGE_GENERATION_SETTLEMENT_REPOSITORY_UNAVAILABLE', '图片用量与创意点持久化结算核验尚未配置', 503, { reconciliation_required: true, provider_succeeded: true })
  }
  const usage = await persistence.modelUsage.listByAction(workspaceId, actionId)
  if (!reservation || reservation.id !== reservationId || reservation.actionKey !== actionId || reservation.status !== 'settled'
    || (isProduction() && (snapshot?.access_mode !== 'POINT_CHARGED' || snapshot?.rate_version !== reservation.rateCardVersion || snapshot?.quoted_points !== reservation.points))
    || usage.length !== 1 || usage[0]?.providerRequestId !== providerRequestId || usage[0]?.modality !== 'image'
    || usage[0]?.settlementStatus !== 'settled' || usage[0]?.costCny === undefined || !Number.isFinite(usage[0].costCny)) {
    throw new DomainError('IMAGE_GENERATION_SETTLEMENT_EVIDENCE_PENDING', '图片 Provider 已返回，但原始创意点预留、图片用量或成本回执尚未完成唯一结算；候选保持待对账', 409, { reconciliation_required: true, provider_succeeded: true, retryable: false })
  }
  const relayProvider = (() => {
    const configured = process.env.MODEL_RELAY_PROVIDER?.trim()
    if (configured) return configured
    try { return process.env.MODEL_RELAY_BASE_URL?.trim() ? new URL(process.env.MODEL_RELAY_BASE_URL).hostname : 'configured-relay' }
    catch { return 'configured-relay' }
  })()
  const verified = await persistence.creativePointLifecycle.verifyModelUsageDeliverySettlement({ workspaceId, reservationId, actionId, providerRequestId, relayProvider })
  if (!verified) throw new DomainError('IMAGE_GENERATION_SETTLEMENT_EVIDENCE_PENDING', '图片 Provider 已返回，但原始扣费动作、双回执与结算操作证据不一致；候选保持待对账', 409, { reconciliation_required: true, provider_succeeded: true, retryable: false })
}

async function chargedImageCandidatesReadable(workspaceId: string, job: import('../../../packages/application/src/service.js').ImageGenerationJob, events?: OutboxEvent[], providerRequestId?: string): Promise<boolean> {
  if (persistence.mode === 'memory' && !isProduction()) return true
  const requested = (events ?? await persistence.outbox?.listAggregateEvents(workspaceId, job.id, 100) ?? []).find(event => event.eventType === 'image.generation.requested')
  if (!requested) {
    const historicalReservation = await persistence.creativePoints?.getReservationByActionKey?.(workspaceId, `image:${job.idempotencyKey}`)
    return !isProduction() && !historicalReservation
  }
  const actionId = typeof requested.payload.action_id === 'string' ? requested.payload.action_id.trim() : ''
  const reservation = actionId ? await persistence.creativePoints?.getReservationByActionKey?.(workspaceId, actionId) : undefined
  const rawSnapshot = requested.payload.commercial_access_snapshot
  const snapshot = rawSnapshot && typeof rawSnapshot === 'object' && !Array.isArray(rawSnapshot) ? rawSnapshot as Record<string, unknown> : undefined
  const charged = Boolean(reservation) || snapshot?.access_mode === 'POINT_CHARGED' || snapshot?.classification === 'POINT_CHARGED'
  if (!charged && !isProduction()) return true
  const identity = providerRequestId ?? (await persistence.imageGenerationExecutions?.get({ workspaceId, jobId: job.id }))?.providerRequestId
  if (!identity) return false
  try {
    await requireChargedImageDeliveryEvidence(workspaceId, job.id, requested, identity)
    return true
  } catch (error) {
    if (error instanceof DomainError && ['IMAGE_GENERATION_COMMERCIAL_SNAPSHOT_INVALID', 'IMAGE_GENERATION_COMMERCIAL_BINDING_INVALID', 'IMAGE_GENERATION_SETTLEMENT_REPOSITORY_UNAVAILABLE', 'IMAGE_GENERATION_SETTLEMENT_EVIDENCE_PENDING'].includes(error.code)) return false
    throw error
  }
}

export function providerSucceededButSettlementPending(error: unknown) {
  if (!error || typeof error !== 'object') return false
  const candidate = error as { code?: unknown; providerSucceeded?: unknown; providerOutcome?: unknown; reconciliationRequired?: unknown; details?: Record<string, unknown> }
  return candidate.providerSucceeded === true || candidate.providerOutcome === 'unknown' || candidate.reconciliationRequired === true
    || candidate.details?.provider_succeeded === true || candidate.details?.provider_outcome === 'unknown' || candidate.details?.reconciliation_required === true
    || candidate.code === 'MODEL_PROVIDER_OUTCOME_UNKNOWN' || candidate.code === 'MODEL_USAGE_SETTLEMENT_PENDING' || candidate.code === 'MODEL_USAGE_COST_MISSING'
}
function requiresStrictAuth() {
  if (process.env.AUTH_ENFORCEMENT === 'strict') return true
  if (['staging', 'preview', 'production'].includes(process.env.NODE_ENV ?? '')) return true
  if (process.env.AUTH_ENFORCEMENT === 'local') return !['development', 'test'].includes(process.env.NODE_ENV ?? '') && process.env.VITEST !== 'true'
  return process.env.NODE_ENV !== 'test' && process.env.VITEST !== 'true'
}

export type RequestPrincipal = {
  actorId: string
  /** Identity subject from the trusted credential store, never request headers. */
  externalSubject?: string
  accountLogin?: string
  /** Verified display metadata only; never use for membership or identity lookup. */
  displayAccountLogin?: string
  /** Set only after server-side credential verification, never from request headers. */
  credentialSource?: 'mcp_oauth'
  workspaces: string[]
  roles: string[]
  workbench: OpsWorkbench
  availableWorkbenches?: OpsWorkbench[]
  /** Trusted credential-store namespace used for workspace binding only. */
  workspaceIdentityIssuer?: string
  issuer?: string
  sessionSubject?: string
  sessionKind?: 'api_token'
  sessionIssuedAt?: string
  sessionExpiresAt?: string
  mfaVerified?: boolean
  identityId?: string
  sessionId?: string
  identityStatus?: 'active' | 'suspended'
  riskDecision?: 'allow' | 'step_up' | 'block'
  memberRole?: MemberRole
  memberStatus?: MemberStatus
  explicitDeniedCapabilities?: CapabilityId[]
  authorizationRevision?: number
  activeAuthorizationGrants?: AuthorizationGrant[]
  platformRoleAssignments?: PlatformRoleAssignment[]
}
const requestPrincipals = new WeakMap<IncomingMessage, RequestPrincipal>()
const requestAuthorizationDecisions = new WeakMap<IncomingMessage, AuthorizationDecision>()
const requestMemberChecks = new WeakSet<IncomingMessage>()
// Set only after the shared capability evaluator has atomically consumed the
// exact durable grant used by this request. Merely having some active grant is
// never enough to bypass workspace membership.
type ConsumedAuthorizationGrantEvidence = {
  grant: AuthorizationGrant
  decisionId: string
  method: string
  capability: CapabilityId
  workspaceId: string
}
const requestConsumedAuthorizationGrants = new WeakMap<IncomingMessage, ConsumedAuthorizationGrantEvidence>()

function exactConsumedGrantForRequest(req: IncomingMessage, workspaceId: string, capability?: CapabilityId) {
  const evidence = requestConsumedAuthorizationGrants.get(req)
  const grant = evidence?.grant
  const decision = requestAuthorizationDecisions.get(req)
  const principal = requestPrincipals.get(req)
  if (!evidence || !grant || !decision || !principal?.identityId || !decision.authorized
    || evidence.decisionId !== decision.decision_id || evidence.method !== decision.method
    || evidence.capability !== decision.capability || evidence.workspaceId !== workspaceId
    || decision.workbench !== 'workspace' || decision.scope.required !== 'workspace'
    || decision.scope.resource_id !== workspaceId || grant.subjectIdentityId !== principal.identityId
    || grant.workspaceId !== workspaceId || !grant.capabilities.includes(decision.capability)
    || capability && decision.capability !== capability
    || !Array.isArray(grant.resourceScope.workspace_ids)
    || grant.resourceScope.workspace_ids.length !== 1 || grant.resourceScope.workspace_ids[0] !== workspaceId) return undefined
  return grant
}
const workerAuthorizedRequests = new WeakSet<IncomingMessage>()
// Unlike development auth bypasses, this map is populated only after a real
// role-bound request signature and nonce have been verified.
const verifiedWorkerRequestRoles = new WeakMap<IncomingMessage, WorkerRequestRole>()
// Authentication is read-heavy, but the durable identity boundary also
// refreshes the identity/session row. Coalesce cold-start observations for
// the same session so a burst of UI requests cannot queue on the same unique
// key and exhaust the API pool.
const authenticatedObservationFlights = new Map<string, Promise<IdentityAuthorizationSnapshot>>()
const testAssetScannerNonces = new Map<string, number>()
const testWorkerNonces = new Map<string, number>()
const workspaceMemberRoles = new Set<MemberRole>(['workspace_owner', 'merchant_admin', 'operator', 'support', 'finance', 'platform_ops'])
// Rules governance is tenant-scoped on the rule-center HTTP boundary and on
// knowledge.rule.create. Keep this explicit gateway role in a workspace
// projection without making any platform-only capability workspace-scoped.
const workspaceGatewayRoles = new Set<CanonicalRole>(['rules_admin'])

function authorizedRoles(principal?: RequestPrincipal) {
  if (!principal) return []
  if (principal.workbench === 'platform') return [...new Set(principal.roles.filter(role => {
    const canonical = canonicalizeRole(role, 'gateway')
    return canonical !== undefined && platformCanonicalRoles.has(canonical)
  }))]
  const gatewayWorkspaceRoles = principal.roles.filter(role => {
    const canonical = canonicalizeRole(role, 'gateway')
    return canonical !== undefined && (!platformCanonicalRoles.has(canonical) || workspaceGatewayRoles.has(canonical)) && !workspaceMemberRoles.has(role as MemberRole)
  })
  return [...new Set([...(principal.memberRole ? [principal.memberRole] : []), ...gatewayWorkspaceRoles])]
}

/**
 * Canonical roles are the only vocabulary an authorization decision may read.
 * `authorizedRoles` deliberately keeps a workspace member's raw membership role
 * for audit output and display, and `platform_ops` is simultaneously a platform
 * gateway role (canonical `ops_admin`) and a workspace membership role that has
 * no canonical form at all. Comparing those raw strings against a gateway
 * allow-list therefore let a workspace member holding the `platform_ops`
 * *membership* role clear platform-operations gates. Every gate derives its
 * answer from this projection so the rule cannot drift site by site.
 */
function canonicalAuthorizationRoles(principal: RequestPrincipal | undefined, rawRoles: readonly string[] = authorizedRoles(principal)): CanonicalRole[] {
  return principal?.workbench === 'workspace'
    ? resolveCanonicalRoles({ gatewayRoles: rawRoles.filter(role => role !== principal.memberRole), memberRole: principal.memberRole })
    : resolveCanonicalRoles({ gatewayRoles: rawRoles })
}

function canonicalAuthorizationRolesForRequest(req: IncomingMessage): CanonicalRole[] {
  return canonicalAuthorizationRoles(requestPrincipals.get(req))
}

/**
 * The canonical form of the durable workspace membership role. Membership is the
 * authority for widening a workspace-scoped boundary (brand scope, tenant
 * scope), so this deliberately ignores gateway assertions.
 */
function canonicalMembershipRole(principal: RequestPrincipal | undefined): CanonicalRole | undefined {
  return principal?.memberRole ? canonicalizeRole(principal.memberRole, 'membership') : undefined
}

const platformCanonicalRoles = new Set<CanonicalRole>(['platform_admin', 'ops_admin', 'support_agent', 'finance_ops', 'security_admin', 'auditor', 'rules_admin', 'model_admin', 'release_admin'])


export function effectiveAuthorizationProjection(principal: RequestPrincipal | undefined, workspaceId: string) {
  return effectiveAuthorizationProjectionWithDependencies(principal, workspaceId, {
    authorizedRoles,
    canonicalAuthorizationRoles,
    workspaceAccountIds: id => workspaceStoreDirectory(id).map(store => store.accountId),
  })
}

const authorizationGovernanceCapabilities = new Set<CapabilityId>([
  'authorization.role.manage', 'authorization.grant.manage', 'workspace.status.update', 'workspace.delete.execute',
  'identity.update', 'identity.session.revoke', 'incident.administer', 'feature_flag.administer', 'audit.export',
  'billing.reconcile.execute', 'billing.refund.execute', 'commercial.update', 'platform.settings.update',
  'platform.media_spec.approve', 'model.policy.update', 'rule.publish.approve', 'canonical.backfill.update',
])

function canonicalRoleMethodAccess(role: CanonicalRole, policy: (typeof MCP_METHOD_POLICIES)[keyof typeof MCP_METHOD_POLICIES]) {
  // Workspace status is a tenant lifecycle control. Platform roles may inspect
  // its governance policy, but only the tenant owner can activate or deactivate
  // a workspace, including while MCP authorization is in shadow mode.
  if (policy.capability === 'workspace.status.update' && role !== 'workspace_owner') return 'hidden' as const
  if (!capabilitiesForRoles([role]).includes(policy.capability)) return 'hidden' as const
  if (policy.effect === 'read') return 'read' as const
  return authorizationGovernanceCapabilities.has(policy.capability) ? 'govern' as const : 'operate' as const
}

/**
 * Resolve the maker-checker approver for the `approval` obligation from
 * server-issued evidence only.
 *
 * The obligation used to be satisfied by the caller-supplied `approved_by` /
 * `approved_at` strings. Nothing proved that an approval act happened, that the
 * named approver existed, was authorised for the target workspace, or differed
 * from the requester, and the value was then persisted into
 * `ops_access_grants.approved_by` and the audit event stream as if it were the
 * record of an approval. The database backstop is only string inequality for
 * write grants (`packages/persistence/src/migrations/105_durable_authorization_grants.sql`
 * `CHECK (access_mode <> 'write' OR approved_by <> issued_by)`), so the proof has
 * to come from the server. This mirrors `parseApprovalGrant`: the approver
 * identity is resolved from a server-side token grant, a claimed `approved_by`
 * may only confirm that identity, and an unparseable token configuration fails
 * closed instead of degrading into an unverified approval.
 */
function verifiedApprovalActor(params: Record<string, unknown>, req: IncomingMessage, workspaceId: string) {
  const token = header(req, 'x-authorization-approval-token')?.trim()
  if (!token) return undefined
  let grants: Record<string, unknown>
  try {
    const parsed: unknown = JSON.parse(process.env.AUTHORIZATION_APPROVAL_TOKENS ?? '{}')
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('invalid')
    grants = parsed as Record<string, unknown>
  } catch { throw new DomainError('AUTHORIZATION_APPROVAL_CONFIG_INVALID', '授权审批令牌配置无效', 503) }
  const matched = Object.keys(grants).find(known => safeEqual(known, token))
  const grant = matched && grants[matched] && typeof grants[matched] === 'object' && !Array.isArray(grants[matched]) ? grants[matched] as Record<string, unknown> : undefined
  const grantActor = typeof grant?.actor_id === 'string' ? grant.actor_id.trim() : ''
  const grantWorkspaces = Array.isArray(grant?.workspaces) ? grant.workspaces.filter((value): value is string => typeof value === 'string') : []
  // Bind the approval to the workspace the operation targets, so a token issued
  // for one tenant cannot approve another tenant's grant request.
  const target = [params.target_workspace_id, params.workspace_id, workspaceId].find((value): value is string => typeof value === 'string' && value.trim().length > 0)?.trim() ?? ''
  const claimedBy = typeof params.approved_by === 'string' ? params.approved_by.trim() : ''
  const actorId = requestPrincipals.get(req)?.actorId
  if (!grantActor || !target || !grantWorkspaces.includes(target)) return undefined
  if (actorId && grantActor === actorId) return undefined
  if (claimedBy && claimedBy !== grantActor) return undefined
  return grantActor
}

export function satisfiedAuthorizationObligations(params: Record<string, unknown>, req: IncomingMessage, workspaceId: string, method?: string) {
  const principal = requestPrincipals.get(req)
  const satisfied: AuthorizationObligation[] = []
  if (typeof params.reason === 'string' && params.reason.trim()) satisfied.push('reason')
  const methodBoundJobRevision = method === 'ops.marketing.generation.no_delivery.refund'
    && typeof params.job_revision === 'string' && /^[1-9][0-9]*$/u.test(params.job_revision)
  if ((typeof params.expected_revision === 'string' && params.expected_revision.trim()) || (typeof params.expected_authorization_revision === 'string' && params.expected_authorization_revision.trim()) || (typeof params.expected_asset_revision === 'string' && params.expected_asset_revision.trim()) || methodBoundJobRevision) satisfied.push('revision')
  if (verifiedApprovalActor(params, req, workspaceId)) satisfied.push('approval')
  const methodBoundActionKey = method === 'ops.marketing.generation.no_delivery.refund'
    && typeof params.action_key === 'string' && params.action_key.trim().length > 0
  if ((typeof params.idempotency_key === 'string' && params.idempotency_key.trim()) || header(req, 'idempotency-key')?.trim() || methodBoundActionKey) satisfied.push('idempotency')
  if ((typeof params.confirmation_hash === 'string' && params.confirmation_hash.trim()) || (typeof params.confirmations_json === 'string' && params.confirmations_json.trim())) satisfied.push('confirmation')
  if (principal?.mfaVerified) satisfied.push('mfa')
  return satisfied
}

export async function resolveLoadedAuthorizationResourceScope(policy: NonNullable<ReturnType<typeof getMcpMethodPolicy>>, workspaceId: string, params: Record<string, unknown>, principal?: Pick<RequestPrincipal, 'actorId'>) {
  return resolveLoadedAuthorizationResourceScopeWithDependencies(policy, workspaceId, params, principal, {
    service,
    ...(persistence.business ? { getTaskSnapshot: (id: string, taskId: string) => persistence.business!.get(id, 'task', taskId) } : {}),
    listCanonicalProducts: input => (persistence.brandUnits ?? memoryBrandUnits).listCanonicalProducts(input),
  })
}

async function permissionAtomsForResolvedResource(req: IncomingMessage, workspaceId: string, policy: NonNullable<ReturnType<typeof getMcpMethodPolicy>>, resourceScope: ReturnType<typeof resolveAuthorizationResourceScope>, atoms: readonly PermissionAtom[], params: Record<string, unknown>) {
  if (resourceScope?.type === 'account' && resourceScope.id) {
    const taskId = typeof params.task_id === 'string' && params.task_id.trim() ? params.task_id.trim() : undefined
    const task = taskId ? service.tasks.get(taskId) : undefined
    if (taskId && (!task || task.workspaceId !== workspaceId || task.accountId !== resourceScope.id)) return atoms
    const scoped = workspaceAccountPermissionAtoms(policy, workspaceId, resourceScope.id, workspaceStoreDirectory(workspaceId).map(store => store.accountId), atoms)
    if (scoped.length !== atoms.length) return scoped.map(atom => atom.sourceId === `workspace-account:${workspaceId}:${resourceScope.id}` ? { ...atom, sourceId: task ? `task-account:${task.id}` : atom.sourceId } : atom)
  }
  if (resourceScope?.type !== 'brand' || !resourceScope.id) return atoms
  const principal = requestPrincipals.get(req)
  const capabilitySource = workspaceCapabilitySourceForBrandScope(policy, workspaceId, atoms)
  if (!principal?.actorId || !capabilitySource) return atoms
  const minimumRole = minimumBrandRoleForPolicy(policy)
  const granted = hasWorkspaceWideBrandAccess(req) || await (persistence.brandUnits ?? memoryBrandUnits).hasBrandAccess({ workspaceId, brandId: resourceScope.id, externalSubject: principal.actorId, minimumRole })
  if (!granted) return atoms
  return [...atoms, { capability: policy.capability, effect: 'allow' as const, scope: { type: 'brand' as const, ids: [resourceScope.id] }, source: 'resource_grant' as const, sourceId: `brand-access:${principal.actorId}:${resourceScope.id}`, obligations: capabilitySource.obligations, ...(capabilitySource.effectLimit ? { effectLimit: capabilitySource.effectLimit } : {}), ...(capabilitySource.expiresAt ? { expiresAt: capabilitySource.expiresAt } : {}), ...(capabilitySource.revision ? { revision: capabilitySource.revision } : {}) }]
}

async function recordAuthorizationDecision(req: IncomingMessage, workspaceId: string, decision: AuthorizationDecision) {
  const correlation = getRequestCorrelation(req)
  enrichRequestObservation(req, {
    authorizationDecisionId: decision.decision_id,
    authorizationPolicyVersion: decision.policy_version,
    authorizationMode: decision.mode,
    authorizationResult: decision.result,
    authorizationReason: decision.reason_code,
    authorizationCapability: decision.capability,
  })
  const actorId = requestPrincipals.get(req)?.actorId
  if (!authorizationDecisionRequiresAudit(decision)) return
  if (decision.workbench === 'platform') {
    if (!actorId) {
      throw new DomainError('AUTHZ_AUDIT_CONTEXT_INVALID', '平台授权审计缺少操作者身份，操作已拒绝', 503, {
        decision_id: decision.decision_id,
        policy_version: decision.policy_version,
      })
    }
    try {
      await (persistence.platformAuthorizationAudit ?? memoryPlatformAuthorizationAudit).append({
        decisionId: decision.decision_id,
        policyVersion: decision.policy_version,
        actorId,
        workbench: 'platform',
        capability: decision.capability,
        method: decision.method,
        result: decision.result === 'allow' || decision.result === 'shadow_allow' ? 'allow' : 'deny',
        reasonCode: decision.reason_code,
        resourceType: decision.scope.required,
        resourceId: decision.scope.resource_id ?? '*',
        resourceScope: { required: decision.scope.required, resolved: decision.scope.resolved.map(scope => ({ type: scope.type, ids: [...scope.ids] })) },
        requestId: correlation.requestId,
        traceId: correlation.traceId,
        evidence: authorizationDecisionAuditEvidence(decision, correlation),
      })
    } catch (error) {
      console.error(`AUTHZ_PLATFORM_AUDIT_UNAVAILABLE decision=${decision.decision_id} method=${decision.method}`, error)
      throw new DomainError('AUTHZ_AUDIT_UNAVAILABLE', '平台授权审计暂不可用，操作已拒绝且未执行', 503, {
        decision_id: decision.decision_id,
        policy_version: decision.policy_version,
      })
    }
    return
  }
  if (!authorizationDecisionAuditContextIsValid(decision, workspaceId, actorId)) {
    throw new DomainError('AUTHZ_AUDIT_CONTEXT_INVALID', '授权审计缺少工作区或操作者身份，操作已拒绝', 503, {
      decision_id: decision.decision_id,
      policy_version: decision.policy_version,
    })
  }
  try {
    await recordOperationAudit({
      workspaceId,
      actorId: actorId!,
      action: 'authz.decision',
      resourceType: 'mcp_method',
      resourceId: decision.method,
      before: {},
      after: authorizationDecisionAuditEvidence(decision, correlation),
      reason: decision.reason_code,
    })
  } catch (error) {
    // An enforced authorization decision without durable audit evidence is not
    // safe to continue: callers must see a stable retry/operational signal,
    // while the sink's internal error and customer data stay server-side.
    console.error(`AUTHZ_AUDIT_UNAVAILABLE decision=${decision.decision_id} method=${decision.method}`, error)
    throw new DomainError('AUTHZ_AUDIT_UNAVAILABLE', '授权审计暂不可用，操作已拒绝且未执行', 503, {
      decision_id: decision.decision_id,
      policy_version: decision.policy_version,
    })
  }
}

async function enforceRegisteredMcpCapability(req: IncomingMessage, workspaceId: string, method: string, params: Record<string, unknown>) {
  const policy = effectiveMcpMethodPolicy(method, params)
  if (!policy) throw new DomainError('AUTHZ_POLICY_UNAVAILABLE', '当前方法缺少服务端授权策略，已拒绝执行', 503, authorizationPolicyUnavailableDetails({ transport: 'mcp', method }))
  if (!requiresStrictAuth()) return policy
  if (['workspace.invitations.list', 'workspace.invitation.accept'].includes(method) && await hasPendingInvitationForPrincipal(req, workspaceId)) return policy
  // Health/onboarding is the authenticated merchant's bootstrap read. It
  // must remain reachable before a membership role projection is hydrated;
  // this does not grant mutation or cross-workspace access.
  const bootstrapPrincipal = requestPrincipals.get(req)
  if (['workspace.health', 'onboarding.status'].includes(method)
    && bootstrapPrincipal?.identityId
    && bootstrapPrincipal.workspaces.includes(workspaceId)
    && !bootstrapPrincipal.explicitDeniedCapabilities?.includes(policy.capability)) return policy
  // A verified identity may resolve its own administrator-assigned binding
  // before membership is hydrated. Strict deployments never grant creation
  // authority through this pre-membership lookup.
  const projection = effectiveAuthorizationProjection(requestPrincipals.get(req), workspaceId)
  const projectedAtoms = method === 'ops.support.tickets.list' && params.platform_scope === 'platform'
    ? [...projection.atoms, ...projection.atoms
      .filter(atom => atom.capability === policy.capability && atom.effect === 'allow' && atom.scope.type !== 'platform')
      .map(atom => ({ ...atom, scope: { type: 'platform' as const, ids: ['*'] } }))]
    : projection.atoms
  const enforce = mcpAuthorizationEnforcedMethods().includes(method as never)
  const principal = requestPrincipals.get(req)
  const resourceScope = params.__http_authorization_scope_conflict === true
    ? { type: policy.scope, id: '__http_path_scope_conflict__' }
    : await resolveLoadedAuthorizationResourceScope(policy, workspaceId, params, principal)
  const decisionAtoms = await permissionAtomsForResolvedResource(req, workspaceId, policy, resourceScope, projectedAtoms, params)
  const decision = registeredMcpAuthorizationDecision({
    decisionId: `authz_${randomUUID()}`,
    method,
    policy,
    atoms: decisionAtoms,
    satisfiedObligations: satisfiedAuthorizationObligations(params, req, workspaceId, policy.method),
    resourceScope,
    workbench: principal?.workbench ?? 'workspace',
    mode: enforce ? 'enforce' : 'shadow',
  })
  if (['workspace.invitations.list', 'workspace.invitation.accept'].includes(method) && await hasPendingInvitationForPrincipal(req, workspaceId)) return policy
  if (method === 'workspace.bootstrap' && !bootstrapPrincipal?.memberRole
    && bootstrapPrincipal?.workbench === 'workspace'
    && Boolean((bootstrapPrincipal.workspaceIdentityIssuer || bootstrapPrincipal.issuer) && bootstrapPrincipal.identityId)) {
    const bootstrapDecision = { ...decision, authorized: true, allowed: true, result: 'shadow_allow' as const, reason_code: 'AUTHZ_ALLOWED' as const }
    await recordAuthorizationDecision(req, workspaceId, bootstrapDecision)
    return policy
  }
  await recordAuthorizationDecision(req, workspaceId, decision)
  requestAuthorizationDecisions.set(req, decision)
  // The `approval` obligation is the maker-checker control on JIT privilege
  // grants and on SLA/commercial approvals. Its provenance is server-only:
  // `verifiedApprovalActor` resolves the approver from a server-issued token
  // (`x-authorization-approval-token`), so the caller-supplied
  // `approved_by`/`approved_at` no longer satisfies it at all.
  //
  // This is the ONE obligation that is enforced regardless of mode, and the
  // reason is the sink: under `strict` the grant handler refuses an unverified
  // approver outright, but in a non-strict deployment it still falls back to
  // persisting `required(params, 'approved_by')`. Letting shadow observe-and-allow
  // here would therefore write a caller-asserted name into
  // `ops_access_grants.approved_by` and the audit stream as though an approval
  // had happened — the exact fabrication this control exists to stop. A shadow
  // allow is only safe for obligations whose failure leaves no false record.
  // Every other obligation keeps the ordinary `allowed = authorized || !enforced`
  // behaviour from `evaluatePermissionAtoms`; see
  // tests/approval-obligation-provenance.test.ts, which pins this exception.
  if (!decision.allowed || decision.obligations.missing.includes('approval')) throw new DomainError(ERROR_CODES.FORBIDDEN, `当前身份授权决策拒绝 ${policy.capability}`, 403, authorizationDenialDetails(decision))
  if (decision.authorized && principal?.identityId) {
    const matches = (atom: PermissionAtom) => atom.capability === policy.capability
      && atom.effect === 'allow'
      && (policy.effect === 'read' || atom.effectLimit !== 'read')
      && atom.scope.type === resourceScope?.type
      && (atom.scope.type === 'platform' && atom.scope.ids.includes('*') || resourceScope?.id !== undefined && (atom.scope.ids.includes(resourceScope.id) || atom.scope.ids.includes('*')))
    const matchingAtoms = projection.atoms.filter(matches)
    const roleOrMembershipAuthorized = matchingAtoms.some(atom => atom.source !== 'temporary_grant')
    const grantAtom = roleOrMembershipAuthorized ? undefined : matchingAtoms.find(atom => atom.source === 'temporary_grant')
    if (grantAtom) {
      const grant = principal.activeAuthorizationGrants?.find(item => item.id === grantAtom.sourceId)
      const repository = authorizationRepository()
      if (!grant || !repository) throw new DomainError('AUTHORIZATION_GRANT_RECHECK_UNAVAILABLE', '临时授权无法在执行前复核，已拒绝操作', 503, authorizationGrantFailureDetails(decision, grant?.id))
      const consumed = await repository.consumeGrant({ id: grant.id, subjectIdentityId: principal.identityId, workspaceId, capability: policy.capability, scopeHash: grant.scopeHash, expectedRevision: grant.revision, actorId: principal.actorId, reason: `mcp:${method}` })
      if (!consumed) throw new DomainError('AUTHORIZATION_GRANT_REVOKED', '临时授权已撤销、过期、耗尽或版本变化，已拒绝操作', 403, authorizationGrantFailureDetails(decision, grant.id))
      principal.activeAuthorizationGrants = principal.activeAuthorizationGrants?.map(item => item.id === consumed.id ? consumed : item)
      principal.authorizationRevision = consumed.authorizationRevision
      requestConsumedAuthorizationGrants.set(req, { grant: consumed, decisionId: decision.decision_id, method, capability: policy.capability, workspaceId })
    }
  }
  return policy
}


async function enforceRegisteredHttpCapability(req: IncomingMessage, url: URL, workspaceId: string): Promise<HttpOperationPolicy | undefined> {
  const httpPolicy = getHttpOperationPolicy(req.method, url.pathname)
  if (!httpPolicy || httpPolicy.authentication !== 'identity' || !httpPolicy.mcpMethod) return httpPolicy
  const mcpPolicy = getMcpMethodPolicy(httpPolicy.mcpMethod)
  if (!mcpPolicy) throw new DomainError('AUTHZ_POLICY_UNAVAILABLE', '当前 HTTP 操作引用的 MCP 授权策略不存在，已拒绝执行', 503, authorizationPolicyUnavailableDetails({ transport: 'http', method: httpPolicy.mcpMethod, operation: httpPolicy.operation }))
  if (mcpPolicy.scope !== 'platform' && workspaceId === 'unknown') throw new DomainError(ERROR_CODES.WORKSPACE_SCOPE_REQUIRED, '当前 HTTP 操作需要明确工作区', 400, { operation: httpPolicy.operation })
  const params: Record<string, unknown> = Object.fromEntries(url.searchParams.entries())
  // DELETE /platform-accounts/:platform accepts the account selector in the
  // header as well as the query string. Bind both transport forms into the
  // shared account resolver before authorization; a missing selector must
  // remain an authorization denial instead of widening to workspace scope.
  if (req.method === 'DELETE' && /^\/v1\/platform-accounts\/(jd|taobao|tmall|pinduoduo|xiaohongshu|douyin)$/u.test(url.pathname)) {
    const accountId = header(req, 'x-account-id')?.trim()
    if (accountId && params.account_id === undefined) params.account_id = accountId
  }
  let pathScopeConflict = false
  const hasJsonAuthorizationParams = httpPolicy.pathTemplate !== '/v1/assets/upload'
    && req.method !== 'GET'
    && (header(req, 'content-type') ?? '').toLowerCase().includes('application/json')
  if (hasJsonAuthorizationParams) Object.assign(params, await body(req))
  // Preserve the publish API's domain error ordering: an account switch on a
  // task already scoped to this workspace is a business conflict (409), not
  // an authorization denial (403). Cross-workspace tasks deliberately skip
  // this check so tenant isolation remains the first boundary.
  if (req.method === 'POST' && url.pathname === '/v1/publish-jobs') {
    const taskId = typeof params.task_id === 'string' && params.task_id.trim() ? params.task_id.trim() : undefined
    const requestedAccountId = typeof params.account_id === 'string' && params.account_id.trim() ? params.account_id.trim() : undefined
    const task = taskId ? service.tasks.get(taskId) : undefined
    if (task?.workspaceId === workspaceId) resolveTaskPublishAccount(task, requestedAccountId)
  }
  const pathParams = httpAuthorizationPathParams(httpPolicy.pathTemplate, url.pathname, httpPolicy.mcpMethod)
  for (const [name, value] of Object.entries(pathParams)) {
    if (typeof params[name] === 'string' && params[name]!.trim() && params[name]!.trim() !== value) {
      // Keep the path authoritative, but let the shared authorization engine
      // produce the denial so HTTP and MCP have the same decision/audit
      // evidence. The marker is internal and never reaches a route handler.
      pathScopeConflict = true
    }
    params[name] = value
  }
  // HTTP routes do not carry the MCP envelope's workspace_id. Bind the
  // already-resolved request scope before evaluating the shared policy so a
  // missing body/query field cannot silently widen or bypass tenant scope.
  params.workspace_id = workspaceId
  if (pathScopeConflict) params.__http_authorization_scope_conflict = true
  await enforceRegisteredMcpCapability(req, workspaceId, httpPolicy.mcpMethod, params)
  return httpPolicy
}

function mcpPolicyMatchesWorkbench(policy: NonNullable<ReturnType<typeof getMcpMethodPolicy>>, workbench: OpsWorkbench) {
  return policy.method === 'platform.model.status'
    || policy.scope === 'self'
    || (workbench === 'platform' && policy.scope === 'platform')
    || (workbench === 'workspace' && policy.scope !== 'platform')
}

async function enforceMcpWorkbenchBoundary(req: IncomingMessage, workspaceId: string, method: string, params: Record<string, unknown>) {
  if (!requiresStrictAuth()) return
  const policy = effectiveMcpMethodPolicy(method, params)
  if (!policy || mcpPolicyMatchesWorkbench(policy, requestPrincipals.get(req)?.workbench ?? 'workspace')) return
  // Resolve the shared authorization decision before any workspace membership,
  // lifecycle, hydration, or handler work. Workbench isolation is an enforced
  // trust boundary even while the capability policy is running in shadow mode.
  await enforceRegisteredMcpCapability(req, workspaceId, method, params)
}

function requestActor(req: IncomingMessage, fallback = 'merchant') {
  const principal = requestPrincipals.get(req)
  return (requiresStrictAuth() ? principal?.actorId : undefined) || header(req, 'x-actor-id')?.trim() || fallback
}

function safeEqual(leftValue: string, rightValue: string) {
  const left = Buffer.from(leftValue)
  const right = Buffer.from(rightValue)
  return left.length === right.length && timingSafeEqual(left, right)
}

function authenticatedSessionHash(rawSessionId: string) {
  const secret = process.env.SESSION_ID_HASH_SECRET?.trim()
  if (!secret) throw new DomainError('SESSION_HASH_SECRET_MISSING', '严格认证环境必须配置独立的会话指纹密钥', 503)
  return createHmac('sha256', secret).update(rawSessionId).digest('hex')
}

async function observeAuthenticatedPrincipal(req: IncomingMessage, principal: RequestPrincipal) {
  if (!requiresStrictAuth() || !principal.issuer || !principal.sessionSubject || !principal.sessionKind || !principal.sessionIssuedAt) return
  assertProductionAuthorizationRuntime()
  await persistenceReady
  const identityRepository = persistence.identities ?? memoryIdentities
  const sessionHash = authenticatedSessionHash(principal.sessionSubject)
  const externalSubject = principal.externalSubject ?? principal.actorId
  const flightKey = `${principal.issuer}\u0000${externalSubject}\u0000${principal.sessionKind}\u0000${sessionHash}`
  try {
    const inFlightObservation = authenticatedObservationFlights.get(flightKey)
    const observation = inFlightObservation ?? identityRepository.observeAuthenticatedSession({
        issuer: principal.issuer,
        externalSubject,
        sessionHash,
        kind: principal.sessionKind,
        issuedAt: principal.sessionIssuedAt,
        ...(principal.sessionExpiresAt ? { expiresAt: principal.sessionExpiresAt } : {}),
        mfaVerified: principal.mfaVerified === true,
        userAgentHash: header(req, 'user-agent') ? authenticatedSessionHash(`ua:${header(req, 'user-agent')}`) : undefined,
      })
    if (!inFlightObservation) {
      authenticatedObservationFlights.set(flightKey, observation)
      void observation.then(() => {
        if (authenticatedObservationFlights.get(flightKey) === observation) authenticatedObservationFlights.delete(flightKey)
      }, () => {
        if (authenticatedObservationFlights.get(flightKey) === observation) authenticatedObservationFlights.delete(flightKey)
      })
    }
    const snapshot = await observation
    principal.identityId = snapshot.identity.id
    principal.sessionId = snapshot.session.id
    principal.identityStatus = snapshot.identity.accessStatus
    principal.riskDecision = snapshot.identity.riskDecision
    if (!snapshot.allowed) throw new DomainError(snapshot.denialReason ?? 'IDENTITY_ACCESS_DENIED', '平台身份、风险或会话状态已拒绝本次访问', 403)
    await hydrateDurableAuthorizationContext(req, principal)
  } catch (error) {
    if (error instanceof DomainError) throw error
    if (error instanceof IdentityLifecycleError) throw new DomainError(error.code, '平台身份或会话状态校验失败', 403)
    throw error
  }
}

async function hydrateDurableAuthorizationContext(req: IncomingMessage, principal: RequestPrincipal) {
  if (!principal.identityId) throw new DomainError('AUTHORIZATION_IDENTITY_REQUIRED', '持久授权上下文缺少平台身份，已拒绝建立受控会话', 503)
  await persistenceReady
  const authzRepository = authorizationRepository()
  if (!authzRepository) throw new DomainError('AUTHORIZATION_REPOSITORY_UNAVAILABLE', '持久授权仓储未配置，已拒绝建立受控会话', 503)
  principal.authorizationRevision = await authzRepository.getAuthorizationRevision(principal.identityId)
  const requestedWorkspace = header(req, 'x-workspace-id')?.trim()
  if (principal.workbench === 'workspace' && requestedWorkspace) {
    principal.activeAuthorizationGrants = await authzRepository.listActiveGrants(principal.identityId, requestedWorkspace)
    if (principal.activeAuthorizationGrants.length) principal.availableWorkbenches = [...new Set<OpsWorkbench>([...(principal.availableWorkbenches ?? []), 'workspace'])]
  }
  if (principal.workbench === 'platform' && process.env.AUTHZ_DURABLE_ASSIGNMENTS_REQUIRED === 'true') {
    const assignments = await authzRepository.listActivePlatformRoles(principal.identityId)
    if (assignments.some(assignment => assignment.role === 'platform_owner')) throw new DomainError('AUTHZ_PLATFORM_ROLE_UNSUPPORTED', 'platform_owner 尚未进入 canonical role contract，已拒绝授权', 503)
    principal.platformRoleAssignments = assignments
    principal.roles = assignments.map(assignment => assignment.role)
    principal.availableWorkbenches = principal.roles.length ? ['platform' as OpsWorkbench] : []
  }
}

function mapIdentityLifecycleError(error: unknown): never {
  if (error instanceof DomainError) throw error
  if (error instanceof IdentityLifecycleError) {
    const status = error.code.endsWith('_NOT_FOUND') ? 404 : error.code.includes('REVISION') || error.code.includes('ALREADY') || error.code.includes('IDEMPOTENCY') ? 409 : 400
    throw new DomainError(error.code, '平台身份生命周期操作失败', status)
  }
  throw error
}

async function consumeAssetScannerNonce(nonce: string): Promise<boolean> {
  if (redisAssetScannerNonce) return redisAssetScannerNonce.consume(nonce, 120)
  if (!process.env.VITEST) throw new DomainError('ASSET_SCANNER_NONCE_STORE_UNAVAILABLE', 'asset scanner nonce store is unavailable', 503)
  const now = Date.now()
  for (const [key, expiresAt] of testAssetScannerNonces) if (expiresAt <= now) testAssetScannerNonces.delete(key)
  if (testAssetScannerNonces.has(nonce)) return false
  testAssetScannerNonces.set(nonce, now + 120_000)
  return true
}

async function consumeWorkerNonce(nonce: string): Promise<boolean> {
  if (redisWorkerNonce) return redisWorkerNonce.consume(nonce, 120)
  if (!process.env.VITEST) throw new DomainError('WORKER_NONCE_STORE_UNAVAILABLE', 'worker request nonce store is unavailable', 503)
  const now = Date.now()
  for (const [key, expiresAt] of testWorkerNonces) if (expiresAt <= now) testWorkerNonces.delete(key)
  if (testWorkerNonces.has(nonce)) return false
  testWorkerNonces.set(nonce, now + 120_000)
  return true
}

/** Production identity boundary: opaque bearer token -> permitted workspaces. */
function authenticationRuntime() {
  return {
    mcpIntegrationMode, isProduction, header, passwordAuthRepository, isTrustedPlatformBrowserOrigin,
    requestPrincipals, hydrateDurableAuthorizationContext, requiresStrictAuth, workspaceMemberRoles,
    requestActor, localPluginTokenContext, safeEqual, CAPABILITIES, canonicalizeRole, platformCanonicalRoles,
    observeAuthenticatedPrincipal, environment: process.env,
  }
}
export type AuthenticationRuntime = ReturnType<typeof authenticationRuntime>

async function authenticate(req: IncomingMessage) {
  return authenticateRequest(req, authenticationRuntime())
}

function requireRuleAdmin(req: IncomingMessage): RequestPrincipal {
  const principal = requestPrincipals.get(req)
  // Compare canonical roles only: matching the raw assertion rejected the
  // registered `platform_rules_admin` gateway alias (canonical `rules_admin`),
  // which made the rule center's writes and lifecycle view unusable for it.
  if (!principal || !canonicalAuthorizationRolesForRequest(req).includes('rules_admin') || !principal.actorId) throw new DomainError(ERROR_CODES.FORBIDDEN, '规则中心写操作需要绑定 actor_id 的 rules_admin 权限', 403)
  const claimedActor = header(req, 'x-actor-id')?.trim()
  if (requiresStrictAuth() && claimedActor && claimedActor !== principal.actorId) throw new DomainError(ERROR_CODES.FORBIDDEN, 'X-Actor-Id 与认证身份不一致', 403)
  return principal
}

function requirePlatformRuleReviewer(req: IncomingMessage): { actorId: string; workbench: string } {
  const principal = requestPrincipals.get(req)
  // Public rule drafts are shared control-plane policy. Do not let the caller
  // widen a workspace principal by asserting x-ops-workbench=platform.
  if (!principal || principal.workbench !== 'platform'
    || !canonicalAuthorizationRolesForRequest(req).includes('rules_admin')
    || !principal.actorId) {
    throw new DomainError(ERROR_CODES.FORBIDDEN, '公共规则草稿审阅需要平台工作台和 rules_admin 身份', 403)
  }
  return { actorId: principal.actorId, workbench: principal.workbench }
}

function requireOperationsRole(req: IncomingMessage, allowed: readonly string[]) {
  const principal = requestPrincipals.get(req)
  const roles = authorizedRoles(principal)
  const canonicalRoles = canonicalAuthorizationRoles(principal, roles)
  const allowedCanonical = new Set(allowed.flatMap(role => [canonicalizeRole(role, 'gateway'), canonicalizeRole(role, 'membership')]).filter((role): role is CanonicalRole => role !== undefined))
  // `platform_ops` is simultaneously a platform gateway role (`ops_admin`) and a
  // workspace membership role. `authorizedRoles` deliberately keeps the raw
  // membership role for audit, so comparing that raw string against an
  // allow-list of *gateway* role names let a workspace member holding the
  // `platform_ops` membership role clear a platform-operations gate — it has no
  // membership canonicalisation, so the canonical branch correctly rejected it
  // while the raw branch let it through. Membership roles are therefore matched
  // only through their canonical form.
  const rawRoles = principal?.workbench === 'workspace' ? roles.filter(role => role !== principal.memberRole) : roles
  if (requiresStrictAuth() && (!principal?.actorId || (!rawRoles.some(role => allowed.includes(role)) && !canonicalRoles.some(role => allowedCanonical.has(role))))) throw new DomainError(ERROR_CODES.FORBIDDEN, '该运营操作需要对应的工作区或平台运营权限', 403)
  return principal?.actorId ?? header(req, 'x-actor-id')?.trim() ?? 'actor_demo'
}

function requirePlatformIdentityMutationRole(req: IncomingMessage, capability: 'identity.update' | 'identity.session.revoke') {
  if (requiresStrictAuth() && requestPrincipals.get(req)?.workbench !== 'platform') {
    throw new DomainError(ERROR_CODES.FORBIDDEN, '身份管理操作必须在平台工作台执行', 403)
  }
  // The registered capability decision remains authoritative (including deny
  // atoms and obligations). Do not contradict it with a legacy platform_ops
  // alias that excludes the platform/security administrators in that contract.
  return requireOperationsRole(req, CANONICAL_ROLES.filter(role => platformCanonicalRoles.has(role) && capabilitiesForRoles([role]).includes(capability)))
}

// Platform read surfaces are available to canonical platform roles carrying
// the corresponding read capability. Mutations keep narrower allow-lists.
function requirePlatformReadRole(req: IncomingMessage) {
  return requireOperationsRole(req, [
    'platform_ops', 'platform_admin', 'ops_admin', 'support_agent', 'finance_ops',
    'security_admin', 'auditor', 'rules_admin', 'model_admin', 'release_admin',
  ])
}

type BillingReadScope = 'mine' | 'workspace'

function billingReadScope(req: IncomingMessage, params: Record<string, unknown>, defaultPrivilegedToWorkspace = false): { scope: BillingReadScope; actorId: string } {
  const principal = requestPrincipals.get(req)
  const privileged = authorizedRoles(principal).some(role => ['workspace_owner', 'merchant_admin', 'finance', 'platform_ops'].includes(role))
  const legacyPersonalBillingMode = process.env.AUTH_ENFORCEMENT === 'strict'
  const requested = params.scope === 'workspace' || (params.scope === undefined && defaultPrivilegedToWorkspace && !legacyPersonalBillingMode && privileged) ? 'workspace' : 'mine'
  const actorId = requestActor(req, 'actor_demo')
  if (requested === 'workspace') requireOperationsRole(req, ['workspace_owner', 'merchant_admin', 'finance', 'platform_ops'])
  return { scope: requested, actorId }
}

/** Customer product/content data is never a platform-wide operations surface. */
function requireWorkspaceDataRole(req: IncomingMessage) {
  const principal = requestPrincipals.get(req)
  const workspaceId = header(req, 'x-workspace-id')?.trim() ?? ''
  if (requiresStrictAuth() && principal?.actorId && exactConsumedGrantForRequest(req, workspaceId)) {
    return principal.actorId
  }
  if (localComposeOpsCustomerDataAccess()) {
    return requireOperationsRole(req, ['workspace_owner', 'merchant_admin', 'operator', 'support', 'platform_ops'])
  }
  return requireOperationsRole(req, ['workspace_owner', 'merchant_admin', 'operator', 'support'])
}

async function enforceCustomerDataAccess(req: IncomingMessage, workspaceId: string, method: string, params: Record<string, unknown> = {}) {
  if (!requiresStrictAuth() || !isPlatformOperations(req) || !isCustomerDataMethod(method, params) || localComposeOpsCustomerDataAccess()) return
  const principal = requestPrincipals.get(req)
  const grant = validateCustomerDataAccessGrant(header(req, 'x-ops-customer-access-grant'), { actorId: principal?.actorId ?? '', workspaceId, method })
  await recordOperationAudit({ workspaceId, actorId: grant.actorId, action: 'ops.customer_data.access', resourceType: 'workspace', resourceId: workspaceId, before: {}, after: { grant_id: grant.grantId, scope: isCustomerDataWriteMethod(method) ? 'customer_data.write' : 'customer_data.read', method, expires_at: new Date(grant.expiresAt * 1000).toISOString() }, reason: '平台运营临时客户数据授权访问' })
}

function isPlatformOperations(req: IncomingMessage) {
  const principal = requestPrincipals.get(req)
  const roles = authorizedRoles(principal)
  // rules_admin is a platform read role, not an operator role: it may see
  // active evidence but must not receive draft/expired customer-control data.
  // Normalize gateway aliases here as well.  authorizedRoles intentionally
  // preserves the raw role for audit/display, so comparing only the raw
  // string would make a signed `platform-ops`/`ops-admin` assertion lose its
  // platform-operator boundary while other capability checks still accept it.
  return principal?.workbench === 'platform' && roles.some(role => {
    const canonical = canonicalizeRole(role, 'gateway')
    return canonical !== undefined && canonical !== 'rules_admin' && platformCanonicalRoles.has(canonical)
  })
}

function canViewRuleLifecycle(req: IncomingMessage) {
  // Canonical roles only. Reading the raw assertion made a workspace member
  // whose *membership* role is `platform_ops` (no canonical form) pass this
  // Ops-only predicate and see inactive and manual:// rows the merchant view
  // must never expose. `platform_admin` stays out deliberately: lifecycle
  // visibility is scoped to the Ops operator and rules-governance roles.
  const roles = canonicalAuthorizationRolesForRequest(req)
  // The MCP bridge and merchant UI share the API, including local bearer
  // credentials that may carry an Ops role. Lifecycle rows are an Ops-only
  // view; use the authenticated principal's workbench, never the client
  // supplied x-ops-workbench header. In OIDC mode that header is not signed
  // and must not be able to widen a workspace session into an Ops view.
  const authenticatedWorkbench = requestPrincipals.get(req)?.workbench
  const requestedWorkbench = header(req, 'x-ops-workbench')?.trim()
  return requestedWorkbench === authenticatedWorkbench
    && (authenticatedWorkbench === 'platform' || authenticatedWorkbench === 'workspace')
    && (roles.includes('rules_admin') || roles.includes('ops_admin'))
}

function scopeCommercialRolloutTarget(req: IncomingMessage, currentWorkspaceId: string, targetWorkspaceId?: string) {
  const target = targetWorkspaceId?.trim() || undefined
  if (isPlatformOperations(req)) return target
  if (!target || target !== currentWorkspaceId) throw new DomainError(ERROR_CODES.FORBIDDEN, '普通工作区运营角色只能管理当前工作区灰度配置', 403)
  return target
}

async function resolveActiveWorkspaceMember(req: IncomingMessage, workspaceId: string, required: boolean) {
  if (!requiresStrictAuth() || requestMemberChecks.has(req)) return true
  const principal = requestPrincipals.get(req)
  if (!principal?.actorId) throw new DomainError(ERROR_CODES.UNAUTHENTICATED, '生产工作区访问必须绑定可识别的成员身份', 401)
  if (!workspaceId) throw new DomainError(ERROR_CODES.FORBIDDEN, '生产工作区访问缺少工作区范围', 403)
  const member = (await (persistence.members ?? memoryMembers).list(workspaceId)).find(item => item.externalSubject === principal.actorId || (principal.accountLogin && item.externalSubject === principal.accountLogin) || (principal.identityId && item.identityId === principal.identityId))
  if (!member) {
    if (required) throw new DomainError('WORKSPACE_MEMBERSHIP_REQUIRED', '当前身份不是该工作区的有效成员，请由工作区所有者邀请后重试', 403, { workspace_id: workspaceId })
    return false
  }
  principal.memberRole = member.role
  principal.memberStatus = member.status
  if (member.status === 'suspended') throw new DomainError('MEMBER_SUSPENDED', '该运营成员已被暂停，当前工作区访问已撤销', 403)
  if (member.status !== 'active') throw new DomainError('MEMBER_NOT_ACTIVE', '该运营成员尚未激活，当前工作区访问未开放', 403)
  if (principal.identityId && member.identityId !== principal.identityId) {
    try { await (persistence.members ?? memoryMembers).bindIdentity({ workspaceId, externalSubject: member.externalSubject, identityId: principal.identityId }) }
    catch (error) { if (String(error).includes('MEMBER_IDENTITY_CONFLICT')) throw new DomainError('MEMBER_IDENTITY_CONFLICT', '成员关系已绑定到其他平台身份，访问已拒绝', 403); throw error }
  }
  const gatewayMemberRoles = principal.roles.filter(role => {
    if (!workspaceMemberRoles.has(role as MemberRole)) return false
    const canonical = canonicalizeRole(role, 'gateway')
    return canonical === undefined || !platformCanonicalRoles.has(canonical)
  })
  if (gatewayMemberRoles.length > 0 && !gatewayMemberRoles.includes(member.role)) throw new DomainError('MEMBER_ROLE_MISMATCH', '身份网关角色与工作区成员角色不一致，访问已拒绝', 403, { member_role: member.role })
  requestMemberChecks.add(req)
  return true
}

async function hasPendingInvitationForPrincipal(req: IncomingMessage, workspaceId: string) {
  const principal = requestPrincipals.get(req)
  const subjects = new Set([principal?.actorId, principal?.accountLogin].filter((value): value is string => Boolean(value)))
  if (!subjects.size || !workspaceId) return false
  const member = (await (persistence.members ?? memoryMembers).list(workspaceId)).find(item => subjects.has(item.externalSubject))
  return member?.status === 'invited'
}

function principalInvitationSubjects(req: IncomingMessage) {
  const principal = requestPrincipals.get(req)
  return new Set([principal?.actorId, principal?.accountLogin].filter((value): value is string => Boolean(value)))
}

async function enforceActiveWorkspaceMember(req: IncomingMessage, workspaceId: string) {
  await resolveActiveWorkspaceMember(req, workspaceId, true)
}

/** Brand profile is a workspace-level customer surface on both HTTP and MCP.
 * Keep the HTTP transport from bypassing the active-member and write-role gates
 * that the MCP route already applies. Platform operators still need the
 * temporary customer-data grant enforced by the shared HTTP preflight. */
async function enforceBrandProfileHttpAccess(req: IncomingMessage, workspaceId: string, write = false) {
  await enforceActiveWorkspaceMember(req, workspaceId)
  if (!requiresStrictAuth() || isPlatformOperations(req)) return
  if (write && !['workspace_owner', 'merchant_admin', 'operator'].includes(requestPrincipals.get(req)?.memberRole ?? '')) {
    throw new DomainError(ERROR_CODES.FORBIDDEN, '品牌资料写入需要工作区所有者、商家管理员或运营角色', 403)
  }
}

