const { refreshCampaignProgress, campaignWorkflow, validateCampaignDelivery, CAMPAIGN_LIFECYCLE_METHODS, assertCampaignLifecycleParams } = createCampaignRuntime({ service, repository: () => persistence.brandUnits ?? memoryBrandUnits })

/**
 * The refund repository and the migration-220/221 triggers enforce the same
 * cumulative bound, but only the repository raises a branded error. A writer
 * that bypasses it (an ops script, a restored replica, a future endpoint) is
 * stopped by the trigger with a raw `23514` check_violation, which used to
 * surface as an unmapped HTTP 500 with no business code the client could act on.
 */
function refundError(error: unknown): never {
  if (error instanceof CommercialRefundRepositoryError) throw new DomainError(error.code, error.message, 409)
  const pointCode = error && typeof error === 'object' && 'code' in error ? (error as { code?: unknown }).code : null
  if (pointCode === 'CREATIVE_POINT_INSUFFICIENT') throw new DomainError(pointCode, '可用创意点不足，已拒绝登记退款；请先核对已使用与待回滚点数', 409)
  if (pointCode === 'CREATIVE_POINT_BALANCE_UNKNOWN') throw new DomainError(pointCode, '创意点余额暂不可确认，已拒绝登记退款', 503)
  if (pointCode === 'CREATIVE_POINT_IDEMPOTENCY_CONFLICT') throw new DomainError(pointCode, '创意点账本状态已变化，请刷新后重新核对退款', 409)
  if (error && typeof error === 'object' && 'code' in error && (error as { code?: unknown }).code === '23514') throw new DomainError('COMMERCIAL_REFUND_STATE_INVALID', '退款金额超过订单实付金额，已拒绝', 409)
  throw error
}

function campaignLifecycleError(error: unknown): never {
  if (!(error instanceof CampaignLifecycleError)) throw error
  const mapped = error.code === 'CAMPAIGN_BATCH_NOT_FOUND' ? { status: 404, message: '批量运营计划不存在或不属于当前工作区' }
    : error.code === 'CAMPAIGN_REVISION_CONFLICT' ? { status: 409, message: 'campaign revision 已变化，请刷新后重试' }
      : error.code === 'CAMPAIGN_LIFECYCLE_IDEMPOTENCY_CONFLICT' ? { status: 409, message: '幂等键已绑定其他 campaign 生命周期操作' }
        : error.code === 'CAMPAIGN_RETRY_ITEM_INVALID' ? { status: 409, message: 'retry_failed 只能选择当前 failed 的 campaign item' }
          : { status: 409, message: 'campaign 当前状态不允许该操作' }
  throw new DomainError(error.code, mapped.message, mapped.status)
}

