const JOB_ADMISSION_TTL_SECONDS = 24 * 60 * 60

async function reserveDistributedJobSlot(workspaceId: string, reservationId: string) {
  if (!redisJobAdmission) return false
  try {
    const acquired = await redisJobAdmission.acquire(workspaceId, reservationId, Math.max(1, Math.floor(maxActiveJobsPerWorkspace)), JOB_ADMISSION_TTL_SECONDS)
    if (acquired === 'quota') throw new DomainError('WORKSPACE_JOB_QUOTA_EXCEEDED', '当前工作区已有较多任务排队，请稍后重试', 429, { limit: maxActiveJobsPerWorkspace, retry_after_seconds: 5 })
    if (acquired === 'existing') throw new DomainError('IDEMPOTENCY_IN_PROGRESS', '相同幂等键的任务正在其他服务实例创建，请稍后重试', 409, { retry_after_seconds: 1 })
    return true
  } catch (error) {
    if (error instanceof DomainError) throw error
    // Redis is an acceleration/coordination dependency. The in-process domain
    // quota remains active and health exposes this degraded mode.
    return false
  }
}

async function hydrateDurableIdempotentJob(workspaceId: string, entityType: 'publish_job' | 'generation_job', idempotencyKey: string) {
  await persistenceReady
  const snapshot = await persistence.business?.findByIdempotencyKey(workspaceId, entityType, idempotencyKey)
  if (snapshot) service.hydrateSnapshot({ entityType, entity: snapshot.payload })
  return snapshot?.payload
}

async function waitForDurableIdempotentJob(workspaceId: string, entityType: 'publish_job' | 'generation_job', idempotencyKey: string) {
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const payload = await hydrateDurableIdempotentJob(workspaceId, entityType, idempotencyKey)
    if (payload) return payload
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  throw new DomainError('IDEMPOTENCY_IN_PROGRESS', '相同幂等键的任务正在其他服务实例创建，请稍后重试', 409, { retry_after_seconds: 1 })
}

async function releaseDistributedJobSlot(workspaceId: string, reservationId: string) {
  if (!redisJobAdmission) return
  try { await redisJobAdmission.release(workspaceId, reservationId) } catch { /* health/alerts surface Redis degradation */ }
}

/** Shared OAuth initiation path for REST and MCP so both surfaces enforce the
 * same redirect, PKCE, state and connector readiness rules. */
const oauthRedirectEnv: Record<Platform, string> = {
  jd: 'JD_OAUTH_REDIRECT_URI',
  taobao: 'TAOBAO_OAUTH_REDIRECT_URI',
  tmall: 'TMALL_OAUTH_REDIRECT_URI',
  pinduoduo: 'PDD_OAUTH_REDIRECT_URI',
  xiaohongshu: 'XHS_OAUTH_REDIRECT_URI',
  douyin: 'DOUYIN_OAUTH_REDIRECT_URI',
}

export function configuredOAuthRedirectUri(platform: Platform, source: NodeJS.ProcessEnv = process.env): string | undefined {
  const platformUri = source[oauthRedirectEnv[platform]]?.trim()
  if (platformUri) return platformUri
  const shared = source.PUBLIC_OAUTH_REDIRECT_URI?.trim()
  if (!shared) return undefined
  if (shared.includes('{platform}')) return shared.replaceAll('{platform}', platform)
  try {
    const parsed = new URL(shared)
    const path = parsed.pathname.replace(/\/+$/u, '')
    if (path.endsWith('/v1/oauth/callback')) {
      parsed.pathname = `${path}/${platform}`
      return parsed.toString()
    }
  } catch { /* validated by the authorization boundary below */ }
  return shared
}

function validOAuthRedirectUri(platform: Platform, redirectUri: string): boolean {
  try {
    const parsed = new URL(redirectUri)
    return parsed.protocol === 'https:' && parsed.pathname.replace(/\/+$/u, '') === `/v1/oauth/callback/${platform}`
  } catch { return false }
}

async function beginPlatformAuthorization(req: IncomingMessage, platform: Platform, input: JsonObject, workspaceId: string) {
  const actorId = requestActor(req, typeof input.actor_id === 'string' && input.actor_id.trim() ? input.actor_id.trim() : 'actor_demo')
  const codeVerifier = randomBytes(32).toString('base64url')
  const configuredRedirectUri = configuredOAuthRedirectUri(platform)
  const requestedRedirectUri = typeof input.redirect_uri === 'string' ? input.redirect_uri.trim() : undefined
  const redirectUri = isProduction() ? configuredRedirectUri ?? '' : requestedRedirectUri ?? configuredRedirectUri ?? 'http://127.0.0.1:8787/oauth/callback'
  if (!redirectUri || (isProduction() && (!validOAuthRedirectUri(platform, redirectUri) || (requestedRedirectUri && requestedRedirectUri !== configuredRedirectUri)))) throw new DomainError('OAUTH_REDIRECT_URI_REQUIRED', `生产 OAuth 必须配置匹配 ${platform} 回调路由的 HTTPS ${oauthRedirectEnv[platform]}（或 PUBLIC_OAUTH_REDIRECT_URI 模板）`, 503)
  if (isProduction() && !oauthStateStoreProductionReady()) throw new DomainError('OAUTH_STATE_STORE_UNAVAILABLE', '生产 OAuth 必须配置 Redis 状态存储，禁止使用单副本内存状态', 503)
  // Do not send a merchant through the provider consent screen when the
  // callback cannot persist the resulting credential.  The credential
  // provider is deliberately checked at the initiation boundary as well as
  // by exchangeCode(), so a production deployment fails closed before it
  // creates one-time state that can never complete.
  if (isProduction() && !fixtureMode && connectorRuntime.isOAuthConfigured(platform) && !connectorRuntime.credentialProviderConfigured) {
    throw new DomainError('NOT_CONFIGURED', '平台 OAuth 已配置，但凭据存储不可用；请先配置 Vault 或外部凭据服务', 503, { reason_code: 'CREDENTIAL_PROVIDER_UNAVAILABLE', platform })
  }
  // Validate the connector before issuing one-time state.  A missing platform
  // configuration must not leave an unusable state entry behind.
  if (!platformAuthorizationConfigured(platform)) throw new DomainError('NOT_CONFIGURED', `${platform} 官方 OAuth 尚未配置`, 503)
  const state = await oauthStateStore().issue({ workspaceId, actorId, platform, codeVerifier, codeChallenge: hashPkceVerifier(codeVerifier) })
  const result = await connectorRuntime.connector(platform).authorize({ workspaceId, actorId, redirectUri, state, codeVerifier })
  if (!result.ok) throw new DomainError(result.code ?? 'NOT_CONFIGURED', result.message ?? '平台官方 API 尚未配置', 503)
  // The local fixture connector intentionally does not invent an external
  // provider URL.  The merchant desktop still needs the issued state to
  // complete its deterministic callback shortcut, so return a non-external
  // continuation URL carrying only the opaque state (never credentials).
  if (result.mode === 'fixture' && !result.authorizationUrl) {
    const continuation = new URL(redirectUri, 'http://127.0.0.1')
    continuation.searchParams.set('state', state)
    return { ...result, authorizationUrl: continuation.toString() }
  }
  return result
}

/**
 * Amortized sweep of the process-local fallback rate buckets.
 *
 * The previous shape walked the whole map on every request whose bucket was
 * missing or expired — i.e. the first request of each 60-second window, a
 * common path — once the map passed `RATE_BUCKET_SWEEP_THRESHOLD`. That is
 * O(new keys per window × map size), and it fires precisely while Redis is
 * down, because the fallback is only reached on a Redis failure: the moment
 * the event loop can least afford a full traversal, the map is at its largest.
 * Entries younger than 60 seconds are not deletable anyway, so a full pass
 * often freed nothing at all.
 *
 * Inspect a fixed slice per call through a resumable iterator instead, so the
 * cost is O(1) amortized per request and a large map is still drained across
 * many requests rather than in one long pause.
 */
const RATE_BUCKET_SWEEP_SLICE = 100
let rateBucketSweepCursor: Iterator<[string, { windowStartedAt: number; count: number }]> | undefined

/** Exported so a unit test can assert the per-call work stays bounded. */
export function sweepExpiredRateBuckets(now: number) {
  if (!rateBucketSweepCursor) rateBucketSweepCursor = rateBuckets.entries()
  for (let inspected = 0; inspected < RATE_BUCKET_SWEEP_SLICE; inspected += 1) {
    const step = rateBucketSweepCursor.next()
    if (step.done) {
      // Restart from the head on the next call; entries inserted since this
      // cursor started are visited by the fresh iterator.
      rateBucketSweepCursor = undefined
      return
    }
    const [key, bucket] = step.value
    if (now - bucket.windowStartedAt >= 60_000) rateBuckets.delete(key)
  }
}

async function enforceRateLimit(req: IncomingMessage, workspaceId: string) {
  if (req.method === 'OPTIONS' || req.url?.startsWith('/healthz')) return
  const principal = requestPrincipals.get(req)
  // The first workspace hydration burst is rate-limited before the OIDC
  // principal is fully projected. A workbench assertion is safe as a rate
  // bucket selector (authorization still rejects spoofed boundaries below),
  // and prevents a legitimate desktop from exhausting the merchant bucket
  // while loading its read-only operational datasets.
  const requestedWorkbench = header(req, 'x-ops-workbench')?.trim()
  const operationsPrincipal = requestedWorkbench === 'platform' || requestedWorkbench === 'workspace'
    || Boolean(principal && authorizedRoles(principal).some(role => ['platform_ops', 'finance', 'workspace_owner', 'merchant_admin', 'operator', 'support'].includes(role)))
  const configuredLimit = Number(operationsPrincipal ? process.env.OPS_API_RATE_LIMIT_PER_MINUTE ?? 600 : process.env.API_RATE_LIMIT_PER_MINUTE ?? DEFAULT_RATE_LIMIT)
  const limit = Number.isFinite(configuredLimit) && configuredLimit > 0 ? configuredLimit : operationsPrincipal ? 600 : DEFAULT_RATE_LIMIT
  const rateScope = `${workspaceId}:${principal?.actorId || 'anonymous'}:${operationsPrincipal ? 'ops' : 'merchant'}`
  const now = Date.now()
  if (redisRateLimit) {
    try {
      const window = Math.floor(now / 60_000)
      const count = await redisRateLimit.increment(`merchant:rate:${rateScope}:${window}`, 120)
      redisRateLimitHealth = { state: 'ready' }
      if (count > limit) {
        const retryAfterSeconds = Math.max(1, 60 - Math.floor((now % 60_000) / 1_000))
        throw new DomainError(ERROR_CODES.RATE_LIMITED, '请求频率超过当前工作区限制', 429, { retry_after_seconds: retryAfterSeconds })
      }
      return
    } catch (error) {
      if (error instanceof DomainError) throw error
      redisRateLimitHealth = { state: 'degraded', lastFailureAt: new Date().toISOString() }
      // Redis outage falls back to the process bucket so a transient cache
      // failure does not take down the API; production health/alerts must
      // surface this degraded protection state.
    }
  }
  const current = rateBuckets.get(rateScope)
  if (!current || now - current.windowStartedAt >= 60_000) {
    // Expired entries were previously left in place, so this fallback map grew
    // one permanent entry per distinct (workspace, actor, scope) for the life of
    // the process — a slow leak on every long-lived replica. Sweep
    // opportunistically instead of adding another timer; the sweep inspects a
    // bounded slice per call so this hot path stays O(1) amortized.
    if (rateBuckets.size >= RATE_BUCKET_SWEEP_THRESHOLD) sweepExpiredRateBuckets(now)
    rateBuckets.set(rateScope, { windowStartedAt: now, count: 1 })
    return
  }
  current.count += 1
  if (current.count > limit) {
    const retryAfterSeconds = Math.max(1, Math.ceil((60_000 - (now - current.windowStartedAt)) / 1_000))
    throw new DomainError(ERROR_CODES.RATE_LIMITED, '请求频率超过当前工作区限制', 429, { retry_after_seconds: retryAfterSeconds })
  }
}

/** Resolve tenant scope from server identity; body/query values are only consistency checks. */
function resolveWorkspace(req: IncomingMessage, candidate?: unknown): string {
  const fromHeader = header(req, 'x-workspace-id')?.trim()
  const principal = requestPrincipals.get(req)
  // A password-authenticated merchant with exactly one assigned workspace has
  // an unambiguous server-side tenant scope. Use it for the first page load so
  // the browser can fetch its workspace context before it knows which header
  // to send. Multi-workspace users and bearer clients must still choose an
  // explicit X-Workspace-Id and remain fail-closed.
  const sessionWorkspace = !fromHeader
    && principal?.sessionKind === 'api_token'
    && principal.workbench === 'workspace'
    && principal.workspaces.length === 1
    ? principal.workspaces[0]
    : undefined
  if (!fromHeader && !sessionWorkspace && requiresStrictAuth()) throw new DomainError(ERROR_CODES.WORKSPACE_SCOPE_REQUIRED, '受控环境请求必须携带 X-Workspace-Id', 401)
  const workspaceId = fromHeader || sessionWorkspace || 'ws_demo'
  // Local Compose capacity tests may use the explicitly opt-in wildcard grant
  // to exercise many isolated workspaces with one test token. Authentication
  // already rejects wildcard grants outside local/non-production mode; keep
  // the tenant resolver consistent with that boundary instead of turning every
  // valid wildcard request into a false cross-tenant denial.
  if (requiresStrictAuth() && principal?.workbench === 'workspace' && principal.workspaces.length > 0
    && !principal.workspaces.includes(workspaceId) && !principal.workspaces.includes('*')) {
    throw new DomainError(ERROR_CODES.FORBIDDEN, '请求工作区与认证身份不一致', 403)
  }
  knownWorkspaces.add(workspaceId)
  if (candidate !== undefined && candidate !== null && String(candidate) !== '' && String(candidate) !== workspaceId) {
    throw new DomainError(ERROR_CODES.WORKSPACE_SCOPE_MISMATCH, '请求工作区与身份工作区不一致', 403)
  }
  return workspaceId
}

function asPlatform(value: unknown): PlatformMediaSpecPlatform | undefined {
  return typeof value === 'string' && PLATFORM_MEDIA_SPEC_PLATFORMS.includes(value as PlatformMediaSpecPlatform)
    ? value as PlatformMediaSpecPlatform
    : undefined
}

function required(input: JsonObject, key: string): string {
  const value = input[key]
  if (typeof value !== 'string' || !value.trim()) throw new DomainError(ERROR_CODES.INVALID_REQUEST, `缺少必填字段: ${key}`, 400)
  return value
}

function requiredOperationalReason(input: JsonObject): string {
  const reason = required(input, 'reason').trim()
  if (reason.length < 4 || reason.length > 500) throw new DomainError(ERROR_CODES.INVALID_REQUEST, 'reason 必须是 4 到 500 个字符', 400)
  return reason
}

function parseJsonObjectParameter(input: JsonObject, key: string): Record<string, unknown> {
  const encoded = required(input, key)
  try {
    const parsed: unknown = JSON.parse(encoded)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('object required')
    return parsed as Record<string, unknown>
  } catch {
    throw new DomainError(ERROR_CODES.INVALID_REQUEST, `${key} 必须是合法 JSON 对象`, 400)
  }
}

function parseJsonArrayParameter(input: JsonObject, key: string): unknown[] {
  const encoded = required(input, key)
  try {
    const parsed: unknown = JSON.parse(encoded)
    if (!Array.isArray(parsed)) throw new Error('array required')
    return parsed
  } catch {
    throw new DomainError(ERROR_CODES.INVALID_REQUEST, `${key} 必须是合法 JSON 数组`, 400)
  }
}

function requiredPositiveInteger(input: JsonObject, key: string, allowZero = false) {
  const value = required(input, key)
  if (!/^\d+$/u.test(value)) throw new DomainError(ERROR_CODES.INVALID_REQUEST, `${key} 必须是整数`, 400)
  const parsed = Number(value)
  if (!Number.isSafeInteger(parsed) || parsed < (allowZero ? 0 : 1)) throw new DomainError(ERROR_CODES.INVALID_REQUEST, `${key} 超出允许范围`, 400)
  return parsed
}

function serviceFulfillmentEventProjection(event: ServiceFulfillmentEventRecord) {
  return {
    id: event.id,
    workspace_id: event.workspaceId,
    allocation_id: event.allocationId,
    event_type: event.type,
    revision: event.revision,
    idempotency_key: event.idempotencyKey,
    actor_id: event.actorId,
    reason: event.reason,
    schedule_at: event.scheduleAt,
    actual_quantity: event.actualQuantity,
    corrects_event_id: event.correctsEventId,
    before: event.before,
    after: event.after,
    evidence: event.evidence,
    created_at: event.createdAt,
  }
}

function throwServiceFulfillmentDomainError(error: unknown): never {
  if (!(error instanceof ServiceFulfillmentRepositoryError)) throw error
  const conflictCodes = new Set([
    'SERVICE_ALLOCATION_IDEMPOTENCY_CONFLICT',
    'SERVICE_FULFILLMENT_IDEMPOTENCY_CONFLICT',
    'SERVICE_FULFILLMENT_REVISION_CONFLICT',
    'SERVICE_FULFILLMENT_TRANSITION_INVALID',
    'SERVICE_FULFILLMENT_PERIOD_EXPIRED',
    'SERVICE_FULFILLMENT_QUOTA_EXCEEDED',
    'SERVICE_FULFILLMENT_CORRECTION_INVALID',
  ])
  const status = error.code === 'SERVICE_ALLOCATION_NOT_FOUND' ? 404 : conflictCodes.has(error.code) ? 409 : 400
  throw new DomainError(error.code, error.message, status)
}

async function appendServiceFulfillmentCommand(
  req: IncomingMessage,
  params: JsonObject,
  type: 'scheduled' | 'started' | 'completed' | 'adjusted',
) {
  const repository = persistence.serviceFulfillment
  if (!repository) throw new DomainError('COMMERCIAL_SERVICE_FULFILLMENT_REPOSITORY_UNAVAILABLE', '服务履约事实仓储尚未配置，禁止写入伪进度', 503)
  const workspaceId = required(params, 'target_workspace_id')
  const evidence = parseJsonObjectParameter(params, 'evidence_json')
  if (Object.keys(evidence).length === 0) throw new DomainError(ERROR_CODES.INVALID_REQUEST, 'evidence_json 不能为空对象', 400)
  try {
    const saved = await repository.appendEvent({
      workspaceId,
      allocationId: required(params, 'allocation_id'),
      type,
      expectedRevision: requiredPositiveInteger(params, 'expected_revision'),
      idempotencyKey: required(params, 'idempotency_key'),
      actorId: requestActor(req),
      reason: requiredOperationalReason(params),
      evidence,
      ...(type === 'scheduled' ? { scheduleAt: required(params, 'schedule_at') } : {}),
      ...(type === 'completed' ? { actualQuantity: requiredPositiveInteger(params, 'actual_quantity') } : {}),
      ...(type === 'adjusted' ? {
        correctsEventId: required(params, 'corrects_event_id'),
        actualQuantity: requiredPositiveInteger(params, 'actual_quantity', true),
      } : {}),
    })
    return {
      schema_version: 'commercial.service-fulfillment-command.v1',
      allocation: projectServiceFulfillment(saved.allocation),
      event: serviceFulfillmentEventProjection(saved.event),
    }
  } catch (error) {
    return throwServiceFulfillmentDomainError(error)
  }
}

function platformGovernanceGatesRequired() {
  if (process.env.REQUIRE_PLATFORM_GOVERNANCE_GATES === 'true') return true
  if (process.env.REQUIRE_PLATFORM_GOVERNANCE_GATES === 'false') return false
  return isProduction() && persistence.mode === 'postgres'
}

function isObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}

function boundedText(value: unknown, label: string, maxLength: number, required = false): string | undefined {
  if (value === undefined && !required) return undefined
  if (typeof value !== 'string' || !value.trim() || value.trim().length > maxLength) throw new DomainError(ERROR_CODES.INVALID_REQUEST, `${label}无效`, 400)
  return value.trim()
}

function readPlatformRejection(value: unknown): PlatformRejection | undefined {
  if (value === undefined) return undefined
  if (!isObject(value)) throw new DomainError(ERROR_CODES.INVALID_REQUEST, '平台拒绝详情无效', 400)
  const fieldsInput = value.fields
  if (!Array.isArray(fieldsInput) || fieldsInput.length > 50) throw new DomainError(ERROR_CODES.INVALID_REQUEST, '平台字段错误必须为不超过 50 项的数组', 400)
  const fields = fieldsInput.map((field, index) => {
    if (!isObject(field)) throw new DomainError(ERROR_CODES.INVALID_REQUEST, `平台字段错误 ${index + 1} 无效`, 400)
    return {
      path: boundedText(field.path, `平台字段错误 ${index + 1} 路径`, 256, true)!,
      ...(field.raw_code === undefined ? {} : { rawCode: boundedText(field.raw_code, `平台字段错误 ${index + 1} 代码`, 128, true)! }),
      message: boundedText(field.message, `平台字段错误 ${index + 1} 原因`, 1000, true)!,
    }
  })
  return {
    rawCode: boundedText(value.raw_code, '平台拒绝代码', 128, true)!,
    ...(value.message === undefined ? {} : { message: boundedText(value.message, '平台拒绝原因', 2000, true)! }),
    fields,
  }
}

function readStaticBrief(value: unknown): StaticBrief | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined
  const brief = value as Record<string, unknown>
  const strings = ['platform', 'placement', 'targetDimensions', 'productImageGuidance', 'logoSafety', 'headline', 'subheadline', 'coreSellingPoint', 'cta', 'textDensity', 'safeArea']
  if (strings.some(key => typeof brief[key] !== 'string' || !(brief[key] as string).trim()) || !Array.isArray(brief.visualHierarchy) || !Array.isArray(brief.protectedAreas)) return undefined
  const visualHierarchy = brief.visualHierarchy.filter((item): item is string => typeof item === 'string' && item.trim().length > 0)
  const protectedAreas = brief.protectedAreas.filter((item): item is string => typeof item === 'string' && item.trim().length > 0)
  if (!visualHierarchy.length || !protectedAreas.length) return undefined
  return {
    platform: brief.platform as string, placement: brief.placement as string, targetDimensions: brief.targetDimensions as string,
    visualHierarchy, productImageGuidance: brief.productImageGuidance as string, logoSafety: brief.logoSafety as string,
    headline: brief.headline as string, subheadline: brief.subheadline as string, coreSellingPoint: brief.coreSellingPoint as string,
    ...(typeof brief.priceExpression === 'string' && brief.priceExpression.trim() ? { priceExpression: brief.priceExpression } : {}),
    cta: brief.cta as string, textDensity: brief.textDensity as string, safeArea: brief.safeArea as string, protectedAreas,
  }
}

export function readContentModules(value: unknown): ContentModule[] | undefined {
  if (value === undefined) throw new DomainError('CONTENT_SCHEMA_INVALID', '异步 worker 的 modules 必须包含 1 至 16 个合法模块', 400)
  if (!Array.isArray(value) || value.length === 0 || value.length > 16) throw new DomainError('CONTENT_SCHEMA_INVALID', '异步 worker 的 modules 必须包含 1 至 16 个合法模块', 400)
  try {
    return validateContentSchema({ title: 'worker-result', detail: 'worker-result', sellingPoints: ['worker-result'], modules: value }, '异步 worker', { requireDecisionContracts: true }).modules
  } catch (error) {
    throw new DomainError('CONTENT_SCHEMA_INVALID', error instanceof Error ? error.message : '异步 worker 的 modules 结构无效', 400)
  }
}

async function archiveCompletedVideo(workspaceId: string, rendering: { status: 'completed' | 'queued'; videoUrl?: string; providerJobId?: string }): Promise<{ status: 'completed' | 'queued'; videoUrl?: string; providerJobId?: string; assetId?: string; archiveState?: 'quarantined' | 'archived' }> {
  if (rendering.status === 'queued') return rendering
  if (!rendering.videoUrl || !rendering.providerJobId) throw new DomainError('VIDEO_ARTIFACT_REFERENCE_INCOMPLETE', '视频 provider 已标记完成，但缺少可归档的 HTTPS artifact URL 或 provider job id', 502)
  const existing = service.findAssetBySourceProviderJobId(workspaceId, rendering.providerJobId)
  if (existing) return { ...rendering, assetId: existing.id, archiveState: isUsableAssetWithoutScan(existing, demoUnscannedAssetsEnabled()) ? 'archived' as const : 'quarantined' as const }
  await assertVideoArtifactUrl(rendering.videoUrl)
  const response = await (videoArtifactFetcherForTestsValue() ?? fetch)(rendering.videoUrl, { method: 'GET', headers: { accept: 'video/mp4, video/webm, video/quicktime' }, redirect: 'error', signal: artifactDownloadSignal() }).catch((error: unknown) => artifactDownloadFailure(error, '视频归档下载失败'))
  if (!response.ok) throw new DomainError('VIDEO_ARTIFACT_DOWNLOAD_FAILED', `视频归档下载失败（HTTP ${response.status}）`, 502)
  const declaredSize = Number(response.headers.get('content-length') ?? '')
  if (Number.isFinite(declaredSize) && declaredSize > MAX_ARCHIVED_VIDEO_BYTES) throw new DomainError('VIDEO_ARTIFACT_TOO_LARGE', '视频归档超过 50MB 限制', 413)
  const body = await readBoundedVideoBody(response, MAX_ARCHIVED_VIDEO_BYTES)
  if (!body.byteLength) throw new DomainError('VIDEO_ARTIFACT_BODY_MISSING', '视频 provider 返回了空二进制内容', 502)
  const mimeType = (response.headers.get('content-type')?.split(';', 1)[0] ?? '').trim().toLowerCase()
  if (!['video/mp4', 'video/webm', 'video/quicktime'].includes(mimeType) || !videoSignatureMatches(mimeType, body)) throw new DomainError('VIDEO_ARTIFACT_SIGNATURE_INVALID', '视频 provider 返回的 MIME 类型或文件签名无法验证，已阻断归档', 502)
  const sha256 = createHash('sha256').update(body).digest('hex')
  const name = `provider-${rendering.providerJobId}.mp4`
  const provisional = service.registerAsset({ workspaceId, name, mimeType, sizeBytes: body.byteLength, sha256, storageKey: `quarantine/${workspaceId}/video_pending_${randomBytes(12).toString('hex')}/${name}`, sourceProviderJobId: rendering.providerJobId, ...(demoUnscannedAssetsEnabled() ? { scanMode: 'unscanned' as const } : {}) })
  if (provisional.deduplication.mode === 'deduplicated') {
    await persistAssetReference(workspaceId, provisional)
    return { ...rendering, assetId: provisional.id, archiveState: isUsableAssetWithoutScan(provisional, demoUnscannedAssetsEnabled()) ? 'archived' as const : 'quarantined' as const }
  }
  let storedKey: string | undefined
  try {
    const stored = await putQuarantineObject({ workspaceId, assetId: provisional.id, fileName: name, contentType: mimeType, body, expectedSha256: sha256, expectedSizeBytes: body.byteLength })
    storedKey = stored.key
    provisional.storageKey = stored.key
    provisional.sha256 = stored.sha256
    provisional.sizeBytes = stored.sizeBytes
    const archiveReference = checkDurableArchiveReference({ kind: 'generated_video', workspaceId, entityId: provisional.id, storageKey: stored.key, sha256: stored.sha256, sizeBytes: stored.sizeBytes, revision: provisional.revision ?? 1 })
    if (!archiveReference.restorable) {
      throw new DomainError('VIDEO_ARCHIVE_CONTRACT_INVALID', '视频已写入隔离对象，但归档引用不满足恢复契约，已阻断结果收敛', 502, { reasons: archiveReference.reasons, asset_id: provisional.id, provider_job_id: rendering.providerJobId })
    }
    await persistAssetSnapshotAndEvent(workspaceId, provisional, demoUnscannedAssetsEnabled() ? 'asset.video_unscanned' : 'asset.video_quarantined', { asset_id: provisional.id, provider_job_id: rendering.providerJobId, storage_key: stored.key, sha256: stored.sha256, size_bytes: stored.sizeBytes, revision: provisional.revision, scan_status: provisional.scanStatus, ...(demoUnscannedAssetsEnabled() ? {} : { next_action: 'asset.scan' }) }, provisional as unknown as Record<string, unknown>)
    return { ...rendering, assetId: provisional.id, archiveState: demoUnscannedAssetsEnabled() ? 'archived' as const : 'quarantined' as const }
  } catch (error) {
    service.assets.delete(provisional.id)
    if (storedKey) await compensateStoredAsset(workspaceId, provisional.id, storedKey, 'video archive metadata or event persistence failed')
    throw error
  }
}

