function requestFailureMetadata(error: unknown) {
  if (isClientDisconnect(error)) return { status: 499, code: 'CLIENT_DISCONNECTED' }
  if (error instanceof OAuthStateError) { const mapped = oauthError(error); return { status: mapped.status, code: mapped.code } }
  if (error instanceof ConnectorFailure) return { status: error.normalized.code === 'UNAUTHORIZED' ? 401 : error.normalized.code === 'NOT_CONFIGURED' ? 503 : error.normalized.code === 'RATE_LIMITED' ? 429 : error.normalized.code === 'NOT_FOUND' ? 404 : 502, code: error.normalized.code }
  if (error instanceof ObjectStorageError) return { status: error.status, code: error.code }
  if (error instanceof ConnectorMappingPreflightError) return { status: 409, code: 'PLATFORM_MAPPING_PREFLIGHT_REQUIRED' }
  if (error instanceof SyncPaginationError && /mapping preflight/iu.test(error.message)) return { status: 409, code: 'PLATFORM_MAPPING_PREFLIGHT_REQUIRED' }
  const authorizationError = authorizationRepositoryDomainError(error)
  if (authorizationError) return { status: authorizationError.status, code: authorizationError.code }
  if (error instanceof DomainError) return { status: error.status, code: error.code }
  return { status: 500, code: ERROR_CODES.INTERNAL_ERROR }
}

export function authorizationRepositoryDomainError(error: unknown): DomainError | undefined {
  if (!(error instanceof AuthorizationRepositoryError)) return undefined
  const status = error.code.endsWith('_NOT_FOUND')
    ? 404
    : error.code.endsWith('_CONFLICT') || error.code.endsWith('_REVISION_CONFLICT')
      ? 409
      : 400
  const message = error.code.endsWith('_NOT_FOUND')
    ? '授权对象不存在或不属于当前工作区'
    : error.code.endsWith('_CONFLICT') || error.code.endsWith('_REVISION_CONFLICT')
      ? '授权状态已变化，请刷新后重试'
      : '授权请求参数无效，请核对后重试'
  return new DomainError(error.code, message, status)
}

function publishCommitDomainError(error: unknown) {
  if (!(error instanceof PublishCommitStatusUnknownError)) return undefined
  return new DomainError(error.code, error.message, 503, { retryable: false, reconciliation_required: true, next_action: 'query_publish_job' })
}

export function modelSettlementDomainError(error: unknown) {
  const code = (error as { code?: unknown })?.code
  if (code === 'MODEL_TASK_COST_ACTUAL_EXCEEDED' || code === 'MODEL_DAILY_COST_ACTUAL_EXCEEDED') return new DomainError(String(code), '模型供应商已完成调用，但实际成本超过安全上限；结果已进入费用核对，不会自动退款或重试', 409, { provider_succeeded: true, reconciliation_required: true })
  if (code === 'MODEL_USAGE_SETTLEMENT_PENDING' || code === 'MODEL_USAGE_COST_MISSING') return new DomainError(String(code), '模型供应商已完成调用，但本地用量结算尚未完成；为避免重复计费，当前结果已阻断且不会自动退款', 503, { provider_succeeded: true, reconciliation_required: true, ...((error as { receiptKey?: unknown }).receiptKey ? { receipt_key: String((error as { receiptKey: unknown }).receiptKey) } : {}) })
  if (code === 'MODEL_PROVIDER_OUTCOME_UNKNOWN') {
    const source = error as { details?: unknown; providerIdempotencyKey?: unknown; providerRequestId?: unknown; status?: unknown }
    const details = source.details && typeof source.details === 'object' && !Array.isArray(source.details) ? source.details as Record<string, unknown> : {}
    const sourceStatus = typeof source.status === 'number' ? source.status : Number.NaN
    const providerStatus = Number.isInteger(sourceStatus) && sourceStatus >= 400 && sourceStatus <= 599 ? sourceStatus : details.provider_status
    const providerRequestId = typeof source.providerRequestId === 'string' && source.providerRequestId.trim() ? source.providerRequestId.trim() : details.provider_request_id
    const providerIdempotencyKey = typeof source.providerIdempotencyKey === 'string' && source.providerIdempotencyKey.trim() ? source.providerIdempotencyKey.trim() : details.provider_idempotency_key
    const providerErrorSummary = typeof details.provider_error_summary === 'string' && details.provider_error_summary.trim() ? details.provider_error_summary.trim().slice(0, 500) : undefined
    return new DomainError('MODEL_PROVIDER_OUTCOME_UNKNOWN', '模型中转请求结果暂时无法确认；已转入后台自动核对，当前任务不会自动重试或重复扣费', 503, {
      provider_succeeded: true, provider_outcome: 'unknown', reconciliation_required: true, retryable: false,
      next_action: 'reconcile_model_request',
      ...(Number.isInteger(providerStatus) ? { provider_status: providerStatus } : {}),
      ...(typeof providerRequestId === 'string' && providerRequestId.length <= 256 ? { provider_request_id: providerRequestId } : {}),
      ...(typeof providerIdempotencyKey === 'string' && providerIdempotencyKey.length <= 256 ? { provider_idempotency_key: providerIdempotencyKey } : {}),
      ...(providerErrorSummary ? { provider_error_summary: providerErrorSummary } : {}),
    })
  }
  if (code === 'MODEL_PROVIDER_REQUEST_FAILED') {
    const source = error as { details?: unknown; status?: unknown; providerRequestId?: unknown }
    const details = source.details && typeof source.details === 'object' && !Array.isArray(source.details) ? source.details as Record<string, unknown> : {}
    const summary = typeof details.provider_error_summary === 'string' && details.provider_error_summary.trim() ? details.provider_error_summary.trim().slice(0, 500) : undefined
    const status = Number.isInteger(source.status) ? Number(source.status) : details.provider_status
    return new DomainError('MODEL_PROVIDER_REQUEST_FAILED', `模型中转服务拒绝了本次请求${summary ? `：${summary}` : ''}`, 502, { provider_succeeded: false, provider_outcome: 'failed', reconciliation_required: false, retryable: false, ...(Number.isInteger(status) ? { provider_status: status } : {}), ...(summary ? { provider_error_summary: summary } : {}) })
  }
  return undefined
}

function isClientDisconnect(error: unknown) {
  if (!(error instanceof Error)) return false
  const code = 'code' in error && typeof error.code === 'string' ? error.code : undefined
  return error.message === 'aborted' || code === 'ECONNRESET' || code === 'ERR_STREAM_PREMATURE_CLOSE'
}

/**
 * A batch request is item-addressed.  Accepting the same task twice would
 * produce duplicate receipts and, depending on processing order, turn a
 * caller mistake into a partial write.  Reject the whole request before any
 * item is authorized, debited, or queued.
 */
function assertUniqueBatchTaskIds(confirmations: Array<Record<string, unknown>>) {
  const taskIds = confirmations.map(item => typeof item.task_id === 'string' ? item.task_id.trim() : '')
  const duplicates = [...new Set(taskIds.filter(Boolean).filter((taskId, index, all) => all.indexOf(taskId) !== index))]
  if (duplicates.length) throw new DomainError('PUBLISH_BATCH_DUPLICATE_TASK', `批量发布请求包含重复任务: ${duplicates.join(', ')}`, 400, { task_ids: duplicates })
}

// `redactSecrets` redacts by key, so it cannot see a credential embedded inside
// a free-text message. Low-level pg/redis/connector errors do embed connection
// strings and bearer tokens, and this log is written to a world-readable file in
// the local launchd profile. Scrub those shapes before emitting.
// Redact the whole userinfo segment rather than trying to preserve the
// username: a password may itself contain `@` or `/` (drivers print the raw
// string, and base64 secrets routinely contain `/`), so a "keep the user, drop
// the password" pattern leaked the password tail — `postgres://u:p@ss@h/db`
// came out as `postgres://u:[REDACTED]@ss@h/db`. Matching greedily to the last
// `@` before whitespace fails safe: at worst it over-redacts a bare `user@host`
// URL, which costs a little diagnostic detail and leaks nothing.
const INLINE_CREDENTIAL_URL = /(\b[a-z][a-z0-9+.-]*:\/\/)[^\s]*@/giu
// Allow optional quotes and the delimiters (`:`, `,`, `=`) that appear in real
// bearer values; an empty username (`redis://:password@host`) is a URL concern,
// not this one. Tokens shorter than 12 characters are left alone by design.
const INLINE_BEARER_TOKEN = /\b(bearer)\s+["']?[A-Za-z0-9._~+/=:,-]{12,}["']?/giu
export function redactInlineCredentials(text: string) {
  return text.replace(INLINE_CREDENTIAL_URL, '$1[REDACTED]@').replace(INLINE_BEARER_TOKEN, '$1 [REDACTED]')
}

const server = createServer((req, res) => {
  const startedAt = process.hrtime.bigint()
  beginRequestObservation(req)
  beginHttpMetric()
  // A request whose socket is destroyed (client abort, upstream timeout) emits
  // 'close' without ever emitting 'finish'. Decrementing only on 'finish' leaked
  // `merchant_http_inflight_requests` upward permanently after the first abort,
  // so any alert or autoscaling signal read from that gauge was permanently
  // inflated. Funnel both events through a single once-guard instead.
  let requestObserved = false
  const observeRequestOnce = (aborted: boolean) => () => {
    if (requestObserved) return
    requestObserved = true
    observeHttpMetric(req, res, startedAt, aborted)
    completeRequestObservation(req, res, aborted)
  }
  res.once('finish', observeRequestOnce(false))
  res.once('close', observeRequestOnce(true))
  route(req, res).catch(error => {
    const settlementError = modelSettlementDomainError(error)
    const publishError = publishCommitDomainError(error)
    const mappedError = settlementError ?? publishError ?? authorizationRepositoryDomainError(error)
    const observedFailure = requestFailureMetadata(mappedError ?? error)
    if (!mappedError && !isClientDisconnect(error) && !(error instanceof DomainError) && !(error instanceof OAuthStateError) && !(error instanceof ConnectorFailure) && !(error instanceof ObjectStorageError) && !(error instanceof ConnectorMappingPreflightError) && !(error instanceof SyncPaginationError)) {
      const correlation = getRequestCorrelation(req)
      console.error(JSON.stringify({
        event: 'request.unhandled_error',
        request_id: correlation.requestId,
        trace_id: correlation.traceId,
        method: req.method,
        route: (req.url ?? '').split('?')[0],
        error_name: error instanceof Error ? error.name : typeof error,
        error_message: redactInlineCredentials(error instanceof Error ? error.message : String(error)),
        error_stack: error instanceof Error && error.stack ? redactInlineCredentials(error.stack) : undefined,
      }))
    }
    // Handlers that answer with a raw `res.end()` (OAuth protocol responses,
    // signed-asset streaming) can still reject after committing the response.
    // Writing again would throw ERR_HTTP_HEADERS_SENT from inside this catch,
    // and that second rejection has no handler: under Node's default
    // --unhandled-rejections=throw it exits the process and drops every other
    // in-flight request on the pod. Bail out once the response is committed.
    if (res.headersSent || res.writableEnded) { res.destroy(); return }
    const workspaceId = (() => { try { return resolveWorkspace(req) } catch { return isProduction() ? 'unknown' : 'ws_demo' } })()
    enrichRequestObservation(req, { workspaceId, actorId: trustedRequestObservationActor(req) })
    failRequestObservation(req, observedFailure.status, observedFailure.code)
    if (isClientDisconnect(error) && (res.destroyed || res.writableEnded)) return
    if (nativeMcpRequests.has(req) && !res.writableEnded) {
      const id = nativeMcpRequestIds.get(req) ?? null
      const code = nativeMcpErrorCode(error)
      // Only a branded DomainError message is safe to return. Anything else
      // maps to -32603 (internal error), and echoing its raw text leaked
      // internal property names and object shapes to the plugin — the REST path
      // already sanitizes to '内部错误'. The original text stays in the
      // `request.unhandled_error` log above.
      const message = error instanceof DomainError && error.message ? error.message : 'MCP 请求处理失败'
      const status = error instanceof DomainError && error.status === 401 ? 401 : 200
      const data = nativeMcpErrorData(error, req)
      return sendNativeMcp(res, status, { jsonrpc: '2.0', id, error: { code, message, ...(data ? { data } : {}) } }, req)
    }
    if (wantsOAuthHtml(req)) {
      const fallback = { status: 500, code: ERROR_CODES.INTERNAL_ERROR, message: '授权回调失败' }
      const mapped = error instanceof OAuthStateError
        ? oauthError(error)
        : error instanceof ConnectorFailure
          ? { status: error.normalized.code === 'UNAUTHORIZED' ? 401 : error.normalized.code === 'NOT_CONFIGURED' ? 503 : error.normalized.code === 'RATE_LIMITED' ? 429 : error.normalized.code === 'NOT_FOUND' ? 404 : 502, code: error.normalized.code, message: error.normalized.message }
          : error instanceof DomainError ? { status: error.status, code: error.code, message: error.message } : fallback
      return sendOAuthCallbackPage(res, mapped.status, { state: 'error', platform: (req.url ?? '').split('/').at(-1)?.split('?')[0] ?? 'store', code: mapped.code, message: 'message' in mapped ? mapped.message : error instanceof Error ? error.message : fallback.message }, req)
    }
    if (error instanceof OAuthStateError) {
      const mapped = oauthError(error)
      return fail(res, mapped.status, workspaceId, mapped.code, error.message, req)
    }
    if (error instanceof ConnectorFailure) {
      const status = error.normalized.code === 'UNAUTHORIZED' ? 401 : error.normalized.code === 'NOT_CONFIGURED' ? 503 : error.normalized.code === 'RATE_LIMITED' ? 429 : error.normalized.code === 'NOT_FOUND' ? 404 : 502
      return fail(res, status, workspaceId, error.normalized.code, error.normalized.message, req)
    }
    if (error instanceof ObjectStorageError) return fail(res, error.status, workspaceId, error.code, error.message, req)
    if (error instanceof ConnectorMappingPreflightError) return fail(res, 409, workspaceId, 'PLATFORM_MAPPING_PREFLIGHT_REQUIRED', '平台字段映射批准缺失、失效或与当前商品载荷不一致', req, { stage: error.stage, next_actions: ['platform.mapping.preflight'] })
    if (error instanceof SyncPaginationError && /mapping preflight/iu.test(error.message)) return fail(res, 409, workspaceId, 'PLATFORM_MAPPING_PREFLIGHT_REQUIRED', '平台字段映射批准缺失、失效或与当前商品载荷不一致', req, { stage: 'sync', next_actions: ['platform.mapping.preflight'] })
    const typed = error instanceof DomainError ? error : mappedError ?? new DomainError(ERROR_CODES.INTERNAL_ERROR, '内部错误', 500)
    const retryAfter = typeof typed.details?.retry_after_seconds === 'number' ? typed.details.retry_after_seconds : undefined
    if (retryAfter !== undefined) res.setHeader('retry-after', String(Math.max(1, Math.ceil(retryAfter))))
    return fail(res, typed.status, workspaceId, typed.code, typed.message, req, typed.details)
  })
})

if (process.env.NODE_ENV !== 'test') {
  let shuttingDown = false
  const shutdownGraceMs = Math.max(1_000, Number(process.env.API_SHUTDOWN_GRACE_MS ?? 15_000))

  // Without a SIGTERM handler the process died instantly on a rolling deploy or
  // an HPA scale-down, resetting requests that had already committed (creative
  // points debited, worker job queued) while kube-proxy was still routing to the
  // pod. Stop accepting first, then drain in-flight work within a bounded window.
  const drainAndExit = (signal: string) => {
    if (shuttingDown) return
    shuttingDown = true
    const forceTimer = setTimeout(() => {
      // A drain that ran out of time is slow, not crashed, but the orchestrator
      // needs a non-zero code to know the pod did not shut down cleanly.
      console.error(JSON.stringify({ event: 'api.shutdown_forced', signal, grace_ms: shutdownGraceMs }))
      server.closeAllConnections()
      process.exit(1)
    }, shutdownGraceMs)
    forceTimer.unref()
    // `closeIdleConnections` only closes sockets that are idle *at the moment it
    // is called*. A request in flight when the drain starts returns to the
    // keep-alive idle state once it finishes, and Node does not reap it until
    // `keepAliveTimeout` (5s by default) — so a single call here made every
    // rolling deploy wait out that timeout and then fall into the forced path,
    // exiting 1. Re-sweep until close() reports every connection is gone.
    const idleSweep = setInterval(() => server.closeIdleConnections(), 250)
    idleSweep.unref()
    server.close(() => {
      // Cancel both timers before the (potentially slow) persistence close, so
      // a long pool shutdown cannot be reported as a forced drain.
      clearInterval(idleSweep)
      clearTimeout(forceTimer)
      void Promise.resolve(persistence.close?.()).catch(() => undefined).then(() => process.exit(0))
    })
  }

  // Node's default --unhandled-rejections=throw turns a single stray rejection
  // into a silent process exit; there was no handler anywhere in the API. Log
  // the cause, then exit non-zero so the orchestrator restarts a process whose
  // state is no longer trustworthy rather than leaving a half-dead pod serving.
  const reportFatal = (event: string, error: unknown) => {
    console.error(JSON.stringify({
      event,
      error_name: error instanceof Error ? error.name : typeof error,
      error_message: redactInlineCredentials(error instanceof Error ? error.message : String(error)),
      error_stack: error instanceof Error && error.stack ? redactInlineCredentials(error.stack) : undefined,
    }))
    if (shuttingDown) return
    shuttingDown = true
    process.exit(1)
  }

  process.once('SIGTERM', drainAndExit)
  process.once('SIGINT', drainAndExit)
  process.on('unhandledRejection', error => reportFatal('process.unhandled_rejection', error))
  process.on('uncaughtException', error => reportFatal('process.uncaught_exception', error))

  persistenceReady.then(() => {
    if (process.env.NODE_ENV === 'development' && process.env.CONNECTOR_FIXTURE_MODE === 'true' && process.env.MERCHANT_TEST_APPROVED_RATES === 'true' && persistence.creativePoints) {
      void persistence.creativePoints.grant({ workspaceId: 'ws_demo', idempotencyKey: 'fixture-bootstrap:ws_demo', sourceType: 'test_fixture', sourceId: 'fixture-bootstrap-ws_demo', points: 10_000, metadata: { fixture: true, non_production: true } }).catch(error => console.error('fixture creative point bootstrap failed', error))
    }
    const cleanupIntervalMs = Math.max(5_000, Number(process.env.ASSET_PROMOTION_CLEANUP_INTERVAL_MS ?? 15_000))
    const cleanupTimer = setInterval(() => { void drainPromotionCleanupTasks() }, cleanupIntervalMs)
    cleanupTimer.unref()
    server.once('close', () => clearInterval(cleanupTimer))
    void drainPromotionCleanupTasks()
    // Operational alerts must be raised by the system, not by a reader: without
    // this tick an alert existed only once an operator opened the console, so a
    // stuck publish or a revoked token produced no row and no webhook.
    const alertSweepTimer = setInterval(() => { void sweepOperationalAlerts() }, OPERATIONAL_ALERT_SWEEP_INTERVAL_MS)
    alertSweepTimer.unref()
    server.once('close', () => clearInterval(alertSweepTimer))
    void sweepOperationalAlerts()
    server.listen(port, process.env.API_BIND_HOST, () => console.log(`merchant API listening on ${JSON.stringify(server.address())} (${persistence.mode})`))
  }).catch(error => {
    console.error('merchant API startup failed: database migration/connection unavailable', error)
    // Do not leave a live Node process with no listener.  Orchestrators can
    // only recover this startup failure when the container actually exits;
    // otherwise the pod stays Running but can never answer its health probe.
    process.exit(1)
  })
}

export { assertUniqueBatchTaskIds, server, service, persistenceReady, memoryMembers as workspaceMembers, memoryOperations as operationAudits, memoryPlatformAuthorizationAudit as platformAuthorizationAuditForTests, memoryCreativePoints as creativePointsForTests, memoryActionLedger as actionLedgerForTests, memoryKnowledge as knowledgeDocumentsForTests, memoryAlerts as operationalAlertsForTests }
